async function loadServerHighRiskApprovalInbox(limit: number): Promise<HighRiskApprovalInbox> {
  const boundedLimit = Math.max(1, Math.min(limit, 25));
  const approvals = (await listActionApprovals({ limit: Math.max(100, boundedLimit * 8) }))
    .filter(isOpenApproval);
  const projects = await listProjectStorageSummaries(1000);
  const projectIds = new Map(projects.map((project) => [project.rootUri, project.id]));
  const projectConfigs = new Map<string, ProjectConfig | null>();
  const items: HighRiskApprovalInbox["items"] = [];
  for (const approval of approvals) {
    if (items.length >= boundedLimit) break;
    if (!projectConfigs.has(approval.projectRootUri)) {
      projectConfigs.set(approval.projectRootUri, await loadLocalProjectConfig(approval.projectRootUri).catch(() => null));
    }
    const project = projectConfigs.get(approval.projectRootUri);
    const classification = project
      ? classifyApprovalAutopilotRisk(approval, project)
      : { eligible: false, risk: "high" as const, reasons: ["Project policy could not be loaded; manual review is required."] };
    if (classification.risk !== "high") continue;
    items.push({
      approvalId: approval.id,
      projectId: projectIds.get(approval.projectRootUri) ?? null,
      projectName: approval.projectName,
      workflowId: approval.workflowId,
      runId: approval.runId,
      approvalStatus: approval.status,
      actionType: approval.actionType,
      target: redactApprovalCardText(approval.target, 240),
      rationale: redactApprovalCardText(approval.rationale, 360),
      risk: "high",
      riskReasons: classification.reasons.map((reason) => redactApprovalCardText(reason, 240)).slice(0, 5),
      requestedAt: approval.createdAt,
      dashboardPath: `/approvals?status=open&run=${encodeURIComponent(approval.runId)}`
    });
  }
  return buildHighRiskApprovalInbox({ scanned: approvals.length, open: approvals.length, items });
}

async function loadServerApprovalPreview(input: {
  projectId: string;
  approvalId: string;
  decision: string;
  actor: string;
  actorRole: string;
  idempotencyKey?: string;
  request?: http.IncomingMessage;
}): Promise<ServerApprovalPreviewReport> {
  const decision = parseServerApprovalDecision(input.decision);
  const projectResolution = await resolveServerProjectReference({ projectId: input.projectId, includeRoot: true });
  const projectRoot = projectResolution.project?.rootUri ?? null;
  const projectConfig = projectRoot ? await loadRegisteredProjectConfig({
    id: projectResolution.project?.projectId ?? input.projectId,
    name: projectResolution.project?.name ?? "unknown",
    rootUri: projectRoot,
    profile: "enterprise",
    config: {},
    updatedAt: "",
    indexedFiles: 0,
    indexedTokens: 0,
    lastIndexedAt: null,
    memoryItems: 0,
    runCount: 0,
    completedRuns: 0,
    failedRuns: 0,
    queuedRuns: 0,
    runningRuns: 0,
    lastRunAt: null,
    lastRunId: null,
    lastWorkflowId: null,
    lastRunStatus: null
  }) : null;
  const approval = input.approvalId.trim() ? await getActionApproval(input.approvalId.trim()).catch(() => null) : null;
  const actionRequiresApprovalDecision = decision === "approve" || decision === "reject" || decision === "approve-and-execute" || decision === "always-approve";
  const actionRequiresExecution = decision === "execute" || decision === "approve-and-execute" || decision === "dismiss";
  const approvalCapability: TeamRoleCapability = decision === "reject" ? "can_reject_actions" : "can_approve_actions";
  const decisionGate = projectConfig && actionRequiresApprovalDecision
    ? evaluateRoleGate(projectConfig, input.actorRole, approvalCapability)
    : null;
  const executionGate = projectConfig && actionRequiresExecution
    ? evaluateRoleGate(projectConfig, input.actorRole, "can_execute_approved_actions")
    : null;
  const separationGate = projectConfig && approval && actionRequiresExecution
    ? evaluateSeparationOfDuties(projectConfig, approval, input.actor)
    : null;
  const policyRecheck = projectConfig && approval
    ? await previewApprovalPolicyRecheck(approval, projectConfig)
    : { status: "not-applicable" as const, detail: "Approval or project config is unavailable." };
  const serverModeEnabled = envFlag("AGENTFLOW_SERVER_MODE");
  const authMode = process.env.AGENTFLOW_SERVER_AUTH?.trim() || "none";
  const authConfigured = authMode === "oidc-proxy" || authMode === "token" && Boolean(process.env.AGENTFLOW_SERVER_TOKEN?.trim());
  const auth = input.request ? validateServerMutationAuth(input.request) : null;
  const idempotencyProvided = Boolean(input.idempotencyKey?.trim());
  const projectMatchesApproval = Boolean(projectRoot && approval && path.resolve(approval.projectRootUri) === path.resolve(projectRoot));
  const roleGateStatus = !actionRequiresApprovalDecision
    ? "pass"
    : !projectConfig
      ? "fail"
    : decisionGate?.allowed
      ? "pass"
      : projectConfig?.team.enforcement === "enforce"
        ? "fail"
        : "warn";
  const executionRoleGateStatus = !actionRequiresExecution
    ? "not-applicable"
    : !projectConfig
      ? "fail"
    : executionGate?.allowed
      ? "pass"
      : projectConfig?.team.enforcement === "enforce"
        ? "fail"
        : "warn";
  const separationStatus = !actionRequiresExecution
    ? "not-applicable"
    : separationGate?.allowed
      ? "pass"
      : projectConfig?.team.separation_of_duties.mode === "enforce"
        ? "fail"
        : "warn";
  const envelope = {
    requestId: `approval_req_${stableHash([input.projectId, input.approvalId, decision, input.actor, new Date().toISOString()]).slice(0, 16)}`,
    idempotencyKey: input.idempotencyKey?.trim() || `approval_preview_${stableHash([input.projectId, input.approvalId, decision, input.actor, input.actorRole]).slice(0, 24)}`,
    actor: input.actor.trim() || "local-preview",
    actorRole: input.actorRole.trim() || "operator",
    projectId: input.projectId.trim(),
    approvalId: input.approvalId.trim(),
    decision,
    source: "server-approval-preview" as const
  };
  const checks: ServerApprovalPreviewReport["checks"] = [
    {
      label: "Project id",
      status: projectResolution.resolved ? "pass" : "fail",
      detail: projectResolution.resolved ? "Project id resolves to one registered project." : projectResolution.reason ?? "Project id did not resolve."
    },
    {
      label: "Approval id",
      status: approval ? "pass" : "fail",
      detail: approval ? "Approval id resolves to one stored approval." : "Approval id is missing, invalid, or unknown."
    },
    {
      label: "Project ownership",
      status: !approval || !projectRoot ? "fail" : projectMatchesApproval ? "pass" : "fail",
      detail: projectMatchesApproval ? "Approval belongs to the resolved registered project." : "Approval project root does not match the registered project id."
    },
    {
      label: "Decision",
      status: "pass",
      detail: `Previewing ${decision}. No approval state will be changed.`
    },
    {
      label: "Decision role",
      status: roleGateStatus,
      detail: decisionGate?.message ?? (actionRequiresApprovalDecision ? "Project config is unavailable; approval/rejection role capability cannot be checked." : "This decision does not require an approval/rejection role capability.")
    },
    {
      label: "Execution role",
      status: executionRoleGateStatus === "not-applicable" ? "pass" : executionRoleGateStatus,
      detail: executionGate?.message ?? (actionRequiresExecution ? "Project config is unavailable; execution role capability cannot be checked." : "This decision does not execute an approved action.")
    },
    {
      label: "Separation of duties",
      status: separationStatus === "not-applicable" ? "pass" : separationStatus,
      detail: separationGate?.message ?? (actionRequiresExecution ? "Approval or project config is unavailable; separation of duties cannot be checked." : "No execution is requested, so separation of duties does not apply.")
    },
    {
      label: "Policy recheck",
      status: policyRecheck.status === "not-applicable" ? "warn" : policyRecheck.status,
      detail: policyRecheck.detail
    },
    {
      label: "Server auth",
      status: input.request
        ? auth?.ok ? "pass" : "fail"
        : !serverModeEnabled ? "warn" : authConfigured ? "pass" : "fail",
      detail: input.request
        ? auth?.ok ? `Authenticated with ${auth.method}.` : auth?.error ?? "Authentication failed."
        : !serverModeEnabled ? "Server mode is disabled; this is a local preview only." : authConfigured ? "Server auth is configured for the selected mode." : "Server auth is required before remote approval/action mutation."
    },
    {
      label: "Idempotency",
      status: idempotencyProvided ? "pass" : "warn",
      detail: idempotencyProvided ? "Client idempotency key is present." : "Preview generated a suggested idempotency key; remote mutation endpoints should require a client-provided key."
    },
    {
      label: "Mutation",
      status: "pass",
      detail: "Preview only. No approval was decided, executed, dismissed, or converted into an always-approve rule."
    }
  ];
  const failures = checks.filter((check) => check.status === "fail").length;
  const warnings = checks.filter((check) => check.status === "warn").length;
  const report: ServerApprovalPreviewReport = {
    kind: "agentflow_server_approval_preview",
    generatedAt: new Date().toISOString(),
    status: failures > 0 ? "blocked" : warnings > 0 ? "attention" : "ready",
    dryRun: true,
    envelope,
    approval: approval ? {
      id: approval.id,
      runId: approval.runId,
      workflowId: approval.workflowId,
      stageId: approval.stageId,
      agentId: approval.agentId,
      status: approval.status,
      actionType: approval.actionType,
      target: approval.target,
      projectRootHash: stableHash(approval.projectRootUri).slice(0, 16),
      executable: isExecutableApprovalAction(approval.actionType)
    } : null,
    controls: {
      serverModeEnabled,
      authMode,
      authConfigured,
      authAccepted: auth ? auth.ok : null,
      projectResolved: projectResolution.resolved,
      approvalResolved: Boolean(approval),
      projectMatchesApproval,
      roleGate: roleGateStatus,
      executionRoleGate: executionRoleGateStatus,
      separationOfDuties: separationStatus,
      policyRecheck: policyRecheck.status,
      idempotencyProvided,
      wouldMutate: false
    },
    checks,
    notes: [
      "This previews the remote approval/action envelope only.",
      "Future remote approval endpoints must reuse this registered project id, actor role, idempotency, policy recheck, auth, and audit shape before mutating approval state.",
      "Local dashboard and MCP approval tools remain the only execution paths today."
    ]
  };
  if (input.request) {
    await safeAppendServerRequestAuditEvent(buildServerApprovalPreviewAuditEvent({
      request: input.request,
      report,
      auth: auth ?? { ok: false, method: "unknown", error: "Authentication was not evaluated." }
    }));
  }
  return report;
}

function parseServerApprovalDecision(value: string): ServerApprovalPreviewReport["envelope"]["decision"] {
  const normalized = value.trim().toLowerCase().replaceAll("_", "-");
  if (normalized === "approve" || normalized === "reject" || normalized === "execute" || normalized === "approve-and-execute" || normalized === "dismiss" || normalized === "always-approve") {
    return normalized;
  }
  return "approve-and-execute";
}

async function previewApprovalPolicyRecheck(
  approval: DashboardActionApproval,
  project: ProjectConfig
): Promise<{ status: "pass" | "warn" | "fail" | "not-applicable"; detail: string }> {
  if (approval.actionType === "local_command") {
    const commandLine = stringFromRecord(approval.payload, "commandLine") ?? approval.target;
    try {
      assertCommandAllowed(commandLine, project);
      return { status: "pass", detail: "Command still passes the project action policy. Execution is not performed." };
    } catch (error) {
      return { status: "fail", detail: `Command policy recheck failed: ${error instanceof Error ? error.message : String(error)}` };
    }
  }
  if (approval.actionType === "file_write") {
    try {
      const fileWrite = await loadApprovedFileWrite(approval);
      assertFileWriteAllowed(fileWrite.path, fileWrite.content, project);
      return { status: "pass", detail: "File write still passes project path and byte policy. File contents were not written." };
    } catch (error) {
      return { status: "fail", detail: `File-write policy recheck failed: ${error instanceof Error ? error.message : String(error)}` };
    }
  }
  if (approval.actionType === "artifact_archive" || approval.actionType === "artifact_restore" || approval.actionType === "artifact_prune" || approval.actionType === "object_mirror") {
    return { status: "warn", detail: `${approval.actionType} has a dedicated execution path; preview confirms envelope controls but leaves the specialized dry-run proof to that action.` };
  }
  if (approval.actionType === "deployment" || approval.actionType === "autonomy") {
    return { status: "not-applicable", detail: `${approval.actionType} records a human decision and does not execute a local side effect.` };
  }
  return { status: "warn", detail: `No policy recheck adapter exists yet for approval action type ${approval.actionType}.` };
}

function formatServerApprovalPreview(report: ServerApprovalPreviewReport): string {
  return [
    `Server approval preview (${report.generatedAt})`,
    `Status: ${report.status}`,
    `Dry run: ${report.dryRun ? "yes" : "no"}`,
    "",
    "Envelope:",
    `- requestId: ${report.envelope.requestId}`,
    `- projectId: ${report.envelope.projectId}`,
    `- approvalId: ${report.envelope.approvalId}`,
    `- decision: ${report.envelope.decision}`,
    `- actorRole: ${report.envelope.actorRole}`,
    `- idempotencyKey: ${report.envelope.idempotencyKey}`,
    "",
    "Approval:",
    ...(report.approval ? [
      `- run: ${report.approval.runId}`,
      `- workflow: ${report.approval.workflowId}`,
      `- stage: ${report.approval.stageId} (${report.approval.agentId})`,
      `- status: ${report.approval.status}`,
      `- action: ${report.approval.actionType} ${report.approval.target}`,
      `- projectRootHash: ${report.approval.projectRootHash}`
    ] : ["- No approval resolved."]),
    "",
    "Checks:",
    ...report.checks.map((check) => `- ${check.status.toUpperCase()} ${check.label}: ${check.detail}`),
    "",
    "Notes:",
    ...report.notes.map((note) => `- ${note}`)
  ].join("\n");
}

async function loadServerApprovalActionReport(input: {
  projectId: string;
  approvalId: string;
  decision: string;
  actor: string;
  actorRole: string;
  idempotencyKey?: string;
  request?: http.IncomingMessage;
  limits?: ReturnType<typeof serverRequestLimits>;
}): Promise<ServerApprovalActionReport> {
  const limits = input.limits ?? serverRequestLimits();
  const preview = await loadServerApprovalPreview(input);
  const auth = input.request ? validateServerMutationAuth(input.request) : null;
  const serverModeEnabled = envFlag("AGENTFLOW_SERVER_MODE");
  const approvalActionExecutionEnabled = envFlag("AGENTFLOW_SERVER_ENABLE_APPROVAL_ACTIONS");
  const clientProvidedIdempotency = Boolean(input.idempotencyKey?.trim());
  const decision = preview.envelope.decision;
  const executeRequested = decision === "execute" || decision === "approve-and-execute";
  const requestHash = stableHash({
    projectId: preview.envelope.projectId,
    approvalId: preview.envelope.approvalId,
    decision,
    actor: preview.envelope.actor,
    actorRole: preview.envelope.actorRole
  });
  const receiptIdempotencyKey = `server-approval-action-${stableHash({
    approvalId: preview.envelope.approvalId,
    decision,
    clientIdempotencyKey: preview.envelope.idempotencyKey
  }).slice(0, 32)}`;
  const rateLimit = input.request
    ? checkServerQueueRateLimit({
        request: input.request,
        actor: preview.envelope.actor,
        limitPerMinute: limits.rateLimitPerMinute
      })
    : { ok: true as const, key: `cli:${preview.envelope.actor}`, limit: limits.rateLimitPerMinute, remaining: limits.rateLimitPerMinute, resetAt: new Date().toISOString() };
  const checks: ServerApprovalActionReport["checks"] = [
    ...preview.checks.filter((check) => check.label !== "Mutation" && check.label !== "Server auth" && check.label !== "Idempotency"),
    {
      label: "Authenticated mutation",
      status: auth ? auth.ok ? "pass" : "fail" : serverModeEnabled ? "warn" : "fail",
      detail: auth
        ? auth.ok ? `Authenticated with ${auth.method}.` : auth.error
        : serverModeEnabled ? "CLI contract validation cannot prove request auth; POST /api/server-approval-action requires auth." : "Server mode is disabled; remote approval/action mutation is blocked."
    },
    {
      label: "Approval action execution gate",
      status: serverModeEnabled && approvalActionExecutionEnabled ? "pass" : "fail",
      detail: serverModeEnabled && approvalActionExecutionEnabled
        ? "Server mode and the approval/action execution gate are explicitly enabled."
        : "Approval/action mutation requires AGENTFLOW_SERVER_MODE=1 and AGENTFLOW_SERVER_ENABLE_APPROVAL_ACTIONS=1."
    },
    {
      label: "Per-action receipt gate",
      status: "pass",
      detail: "Every decision path writes a request-bound durable receipt and reuses it on duplicate idempotency keys."
    },
    {
      label: "Client idempotency",
      status: clientProvidedIdempotency ? "pass" : "fail",
      detail: clientProvidedIdempotency ? "Client idempotency key is present." : "Approval/action mutation requests require a client-provided idempotency key."
    },
    {
      label: "Request limits",
      status: "pass",
      detail: `JSON body limit is ${limits.maxBodyBytes} bytes. Approval/action rate limit is ${limits.rateLimitPerMinute <= 0 ? "disabled" : `${limits.rateLimitPerMinute} request(s) per minute per actor/IP`}.`
    },
    {
      label: "Approval/action rate limit",
      status: rateLimit.ok ? "pass" : "fail",
      detail: rateLimit.ok
        ? `Rate limit accepted for ${rateLimit.key}; ${rateLimit.limit <= 0 ? "unlimited" : `${rateLimit.remaining} remaining`} until ${rateLimit.resetAt}.`
        : `Rate limit exceeded for ${rateLimit.key}; try again after ${rateLimit.resetAt}.`
    },
    { label: "Mutation readiness", status: "pass", detail: "The storage-backed mutation path is available after all preceding gates pass." }
  ];
  let mutation: ServerApprovalActionReport["mutation"] = null;
  const approvalBefore = input.approvalId.trim() ? await getActionApproval(input.approvalId.trim()).catch(() => null) : null;
  const mutationGatesPass = Boolean(Boolean(input.request)
    && checks.filter((check) => check.label !== "Mutation").every((check) => check.status !== "fail")
    && (decision !== "execute" && decision !== "approve-and-execute" && decision !== "dismiss" || preview.controls.policyRecheck === "pass")
    && approvalBefore);
  const lease = mutationGatesPass
    ? await acquireServerApprovalActionLease(receiptIdempotencyKey)
    : { acquired: false, detail: "Shared reservation was not attempted because another mutation gate failed.", release: async () => undefined };
  checks.push({
    label: "Shared idempotency reservation",
    status: mutationGatesPass ? lease.acquired ? "pass" : "fail" : "warn",
    detail: lease.detail
  });
  const canMutate = mutationGatesPass && lease.acquired;
  if (canMutate && approvalBefore) try {
    const previous = await findRunActionByIdempotencyKey({
      runId: approvalBefore.runId,
      artifactKind: "server_approval_action",
      idempotencyKey: receiptIdempotencyKey
    });
    if (previous) {
      const storedHash = stringFromRecord(previous.content, "requestHash");
      if (storedHash !== requestHash) {
        checks.push({ label: "Idempotency replay", status: "fail", detail: "The idempotency key was already used with a different request envelope." });
      } else {
        mutation = {
          receiptUri: previous.uri,
          receiptHash: stableHash(previous.content),
          requestHash,
          replayed: true,
          outcome: stringFromRecord(previous.content, "outcome") === "completed" ? "completed" : "failed",
          title: stringFromRecord(previous.content, "title") ?? "Stored approval action result",
          output: stringFromRecord(previous.content, "output") ?? "Stored result reused.",
          beforeStatus: stringFromRecord(previous.content, "beforeStatus") ?? null,
          afterStatus: stringFromRecord(previous.content, "afterStatus") ?? null,
          rollbackEvidence: Array.isArray(previous.content.rollbackEvidence) ? previous.content.rollbackEvidence.filter((item): item is string => typeof item === "string") : []
        };
        checks.push({ label: "Idempotency replay", status: "pass", detail: `Reused durable result ${previous.uri}; no action was executed again.` });
      }
    } else {
      let result: DashboardFollowUpResult;
      if (decision === "approve") {
        const decided = await decideActionApproval({ approvalId: approvalBefore.id, decision: "approved", actor: preview.envelope.actor, actorRole: preview.envelope.actorRole, note: "Remote approval request." });
        result = decided ? { ok: true, title: "Action approved", runId: decided.runId, output: `Approval ${decided.id} was approved and its decision receipt was recorded.` } : { ok: false, error: "Approval was not pending." };
      } else if (decision === "reject") {
        const decided = await decideActionApproval({ approvalId: approvalBefore.id, decision: "rejected", actor: preview.envelope.actor, actorRole: preview.envelope.actorRole, note: "Remote rejection request." });
        result = decided ? { ok: true, title: "Action rejected", runId: decided.runId, output: `Approval ${decided.id} was rejected and its decision receipt was recorded.` } : { ok: false, error: "Approval was not pending." };
      } else if (decision === "execute") {
        result = await executeApprovedAction({ approvalId: approvalBefore.id, actor: preview.envelope.actor, actorRole: preview.envelope.actorRole });
      } else if (decision === "approve-and-execute") {
        result = await approveAndExecuteAction({ approvalId: approvalBefore.id, actor: preview.envelope.actor, approveActorRole: preview.envelope.actorRole, executeActorRole: preview.envelope.actorRole, note: "Remote approve-and-execute request." });
      } else if (decision === "dismiss") {
        result = await dismissApprovedAction({ approvalId: approvalBefore.id, actor: preview.envelope.actor, actorRole: preview.envelope.actorRole, note: "Remote dismissal request." });
      } else {
        result = await processDashboardApprovalRuleAction({ approvalId: approvalBefore.id, target: approvalRuleExactTarget(approvalBefore), actor: preview.envelope.actor, actorRole: preview.envelope.actorRole, note: "Remote exact-scope always-approve request.", approveCurrent: true });
      }
      const approvalAfter = await getActionApproval(approvalBefore.id).catch(() => null);
      const rollbackEvidence = [
        `approval:${approvalBefore.id}:before=${approvalBefore.status}:after=${approvalAfter?.status ?? "missing"}`,
        `policySnapshotHash=${stringFromRecord(approvalBefore.policyDecision, "policySnapshotHash") ?? "unavailable"}`,
        `requestHash=${requestHash}`,
        decision === "always-approve" ? "ruleScope=exact" : "approval state can be inspected from the preserved action receipt"
      ];
      const receiptContent = {
        idempotencyKey: receiptIdempotencyKey,
        requestHash,
        requestId: preview.envelope.requestId,
        projectId: preview.envelope.projectId,
        approvalId: approvalBefore.id,
        decision,
        actorHash: hashAuditValue(preview.envelope.actor),
        actorRole: preview.envelope.actorRole,
        outcome: result.ok ? "completed" : "failed",
        title: result.ok ? result.title : "Approval action failed",
        output: result.ok ? result.output : result.error,
        beforeStatus: approvalBefore.status,
        afterStatus: approvalAfter?.status ?? null,
        rollbackEvidence
      };
      const receiptUri = await recordRunAction({
        runId: approvalBefore.runId,
        taskId: approvalBefore.taskId,
        agentId: approvalBefore.agentId,
        actionType: `server_approval_${decision}`,
        target: approvalBefore.target,
        summary: result.ok ? result.title : result.error,
        artifactKind: "server_approval_action",
        artifactContent: receiptContent,
        idempotencyKey: receiptIdempotencyKey
      });
      mutation = { receiptUri, receiptHash: stableHash(receiptContent), requestHash, replayed: false, outcome: result.ok ? "completed" : "failed", title: receiptContent.title, output: receiptContent.output, beforeStatus: approvalBefore.status, afterStatus: approvalAfter?.status ?? null, rollbackEvidence };
      checks.push({ label: "Mutation", status: result.ok ? "pass" : "fail", detail: result.ok ? `Mutation completed and durable receipt ${receiptUri} was recorded.` : `Mutation failed and a durable failure receipt was recorded: ${result.error}` });
    }
  } finally {
    await lease.release();
  }
  const failures = checks.filter((check) => check.status === "fail").length;
  const warnings = checks.filter((check) => check.status === "warn").length;
  const report: ServerApprovalActionReport = {
    kind: "agentflow_server_approval_action_report",
    generatedAt: new Date().toISOString(),
    status: failures > 0 ? "blocked" : warnings > 0 ? "attention" : "ready",
    dryRun: !mutation,
    envelope: {
      ...preview.envelope,
      source: "server-approval-action"
    },
    approval: preview.approval,
    controls: {
      ...preview.controls,
      authAccepted: auth ? auth.ok : preview.controls.authAccepted,
      executeRequested,
      approvalActionExecutionEnabled,
      clientProvidedIdempotency,
      requestBodyMaxBytes: limits.maxBodyBytes,
      rateLimitPerMinute: limits.rateLimitPerMinute,
      rateLimitAccepted: rateLimit.ok,
      perActionReceiptGate: true,
      sharedReservationAcquired: lease.acquired,
      wouldMutate: canMutate
    },
    mutation,
    checks,
    notes: [
      "This is the governed remote approval/action endpoint contract.",
      "Mutation is disabled by default and requires both server mode and the dedicated approval-action gate.",
      "Execution reuses the local approval paths; each remote request records a durable request-bound result and duplicate keys return that result without rerunning the action.",
      "A shared Redis reservation serializes receipt lookup, mutation, and receipt creation across server processes; unavailable or contended coordination fails closed."
    ]
  };
  if (input.request) {
    await safeAppendServerRequestAuditEvent(buildServerApprovalActionAuditEvent({
      request: input.request,
      report,
      auth: auth ?? { ok: false, method: "unknown", error: "Authentication was not evaluated." },
      rateLimit
    }));
  }
  return report;
}

function formatServerApprovalActionReport(report: ServerApprovalActionReport): string {
  return [
    `Server approval action endpoint (${report.generatedAt})`,
    `Status: ${report.status}`,
    `Dry run: ${report.dryRun ? "yes" : "no"}`,
    "",
    "Envelope:",
    `- requestId: ${report.envelope.requestId}`,
    `- projectId: ${report.envelope.projectId}`,
    `- approvalId: ${report.envelope.approvalId}`,
    `- decision: ${report.envelope.decision}`,
    `- actorRole: ${report.envelope.actorRole}`,
    `- idempotencyKey: ${report.envelope.idempotencyKey}`,
    "",
    "Controls:",
    `- serverModeEnabled: ${report.controls.serverModeEnabled}`,
    `- approvalActionExecutionEnabled: ${report.controls.approvalActionExecutionEnabled}`,
    `- clientProvidedIdempotency: ${report.controls.clientProvidedIdempotency}`,
    `- perActionReceiptGate: ${report.controls.perActionReceiptGate}`,
    `- sharedReservationAcquired: ${report.controls.sharedReservationAcquired}`,
    `- wouldMutate: ${report.controls.wouldMutate}`,
    ...(report.mutation ? [
      `- replayed: ${report.mutation.replayed}`,
      `- outcome: ${report.mutation.outcome}`,
      `- receipt: ${report.mutation.receiptUri}`,
      `- beforeStatus: ${report.mutation.beforeStatus ?? "unknown"}`,
      `- afterStatus: ${report.mutation.afterStatus ?? "unknown"}`
    ] : []),
    "",
    "Checks:",
    ...report.checks.map((check) => `- ${check.status.toUpperCase()} ${check.label}: ${check.detail}`),
    "",
    "Notes:",
    ...report.notes.map((note) => `- ${note}`)
  ].join("\n");
}

async function processServerQueueRequest(request: http.IncomingMessage, body: unknown, limits = serverRequestLimits()): Promise<ServerQueueReport> {
  const payload = objectValue(body);
  const executeRequested = payload.execute === true;
  const routePreview = await loadServerRoutePreview({
    projectId: stringValue(payload.projectId) ?? "",
    workflowId: stringValue(payload.workflow) ?? stringValue(payload.workflowId) ?? "",
    task: stringValue(payload.task) ?? "",
    actor: stringValue(payload.actor) ?? "server-client",
    actorRole: stringValue(payload.actorRole) ?? "operator",
    idempotencyKey: stringValue(payload.idempotencyKey) ?? undefined
  });
  const auth = validateServerMutationAuth(request);
  const queueExecutionEnabled = envFlag("AGENTFLOW_SERVER_ENABLE_QUEUE");
  const serverModeEnabled = envFlag("AGENTFLOW_SERVER_MODE");
  const clientProvidedIdempotency = Boolean(stringValue(payload.idempotencyKey)?.trim());
  const rateLimit = checkServerQueueRateLimit({
    request,
    actor: routePreview.envelope.actor,
    limitPerMinute: limits.rateLimitPerMinute
  });
  const checks: ServerQueueReport["checks"] = [
    ...routePreview.checks,
    {
      label: "Authenticated mutation",
      status: auth.ok ? "pass" : "fail",
      detail: auth.ok ? `Authenticated with ${auth.method}.` : auth.error
    },
    {
      label: "Queue execution gate",
      status: !executeRequested ? "warn" : serverModeEnabled && queueExecutionEnabled ? "pass" : "fail",
      detail: !executeRequested
        ? "Dry-run preview only. Set execute=true to request queueing."
        : serverModeEnabled && queueExecutionEnabled
          ? "Server mode and queue execution are explicitly enabled."
          : "Queueing requires AGENTFLOW_SERVER_MODE=1 and AGENTFLOW_SERVER_ENABLE_QUEUE=1."
    },
    {
      label: "Client idempotency",
      status: clientProvidedIdempotency ? "pass" : "fail",
      detail: clientProvidedIdempotency ? "Client idempotency key is present." : "Queue requests require a client-provided idempotency key."
    },
    {
      label: "Request limits",
      status: "pass",
      detail: `JSON body limit is ${limits.maxBodyBytes} bytes. Queue rate limit is ${limits.rateLimitPerMinute <= 0 ? "disabled" : `${limits.rateLimitPerMinute} request(s) per minute per actor/IP`}.`
    },
    {
      label: "Queue rate limit",
      status: rateLimit.ok ? "pass" : "fail",
      detail: rateLimit.ok
        ? `Rate limit accepted for ${rateLimit.key}; ${rateLimit.limit <= 0 ? "unlimited" : `${rateLimit.remaining} remaining`} until ${rateLimit.resetAt}.`
        : `Rate limit exceeded for ${rateLimit.key}; try again after ${rateLimit.resetAt}.`
    }
  ];
  let queuedRun: ServerQueueReport["queuedRun"] = null;
  const canQueue = executeRequested
    && routePreview.status !== "blocked"
    && routePreview.route
    && auth.ok
    && serverModeEnabled
    && queueExecutionEnabled
    && clientProvidedIdempotency
    && rateLimit.ok;
  if (canQueue && routePreview.route) {
    const existingRun = await findServerQueueRunByIdempotency({
      projectId: routePreview.route.projectId,
      projectRootUri: routePreview.route.projectRootUri,
      workflowId: routePreview.route.workflowId,
      idempotencyKey: routePreview.envelope.idempotencyKey
    });
    if (existingRun) {
      queuedRun = {
        runId: existingRun.runId,
        projectId: existingRun.projectId,
        projectRootUri: routePreview.route.projectRootUri,
        workflowId: existingRun.workflowId,
        tasks: existingRun.tasks,
        runUrl: `/run?id=${encodeURIComponent(existingRun.runId)}`,
        actorReceiptUri: null,
        reused: true
      };
      checks.push({
        label: "Workflow queue",
        status: "pass",
        detail: `Reused existing workflow run ${existingRun.runId} for this idempotency key.`
      });
    } else {
      const queued = await queueWorkflow({
        workflowId: routePreview.route.workflowId,
        projectPath: routePreview.route.projectRootUri,
        task: routePreview.route.task,
        policyProfile: routePreview.route.policyProfile,
        evaluationMetadata: {
          source: "server-queue",
          requestId: routePreview.envelope.requestId,
          idempotencyKey: routePreview.envelope.idempotencyKey,
          actor: routePreview.envelope.actor,
          actorRole: routePreview.envelope.actorRole,
          authMethod: auth.method
        }
      });
      if (queued.ok) {
        const actorReceiptUri = await recordRunAction({
          runId: queued.run.runId,
          agentId: "workflow-orchestrator",
          actionType: "server_queue_request",
          target: routePreview.route.projectId,
          summary: `Server queue request from ${routePreview.envelope.actor} as ${routePreview.envelope.actorRole}`,
          artifactKind: "server_queue_request",
          artifactContent: {
            requestId: routePreview.envelope.requestId,
            idempotencyKey: routePreview.envelope.idempotencyKey,
            actor: routePreview.envelope.actor,
            actorRole: routePreview.envelope.actorRole,
            authMethod: auth.method,
            projectId: routePreview.route.projectId,
            workflowId: routePreview.route.workflowId,
            policyProfile: routePreview.route.policyProfile,
            receivedAt: new Date().toISOString()
          },
          idempotencyKey: `server-queue-${stableHash(routePreview.envelope.idempotencyKey).slice(0, 24)}`
        });
        queuedRun = {
          runId: queued.run.runId,
          projectId: queued.run.projectId,
          projectRootUri: queued.projectDir,
          workflowId: queued.workflow.id,
          tasks: queued.run.tasks,
          runUrl: `/run?id=${encodeURIComponent(queued.run.runId)}`,
          actorReceiptUri,
          reused: false
        };
        checks.push({
          label: "Workflow queue",
          status: "pass",
          detail: `Queued workflow run ${queued.run.runId}.`
        });
      } else {
        checks.push({
          label: "Workflow queue",
          status: "fail",
          detail: queued.error
        });
      }
    }
  }
  const failures = checks.filter((check) => check.status === "fail").length;
  const warnings = checks.filter((check) => check.status === "warn").length;
  const status: ServerQueueReport["status"] = queuedRun
    ? "queued"
    : failures > 0
      ? "blocked"
      : warnings > 0
        ? "attention"
        : "ready";
  const report: ServerQueueReport = {
    kind: "agentflow_server_queue_report",
    generatedAt: new Date().toISOString(),
    status,
    dryRun: !queuedRun,
    envelope: routePreview.envelope,
    route: routePreview.route,
    queuedRun,
    controls: {
      ...routePreview.controls,
      authAccepted: auth.ok,
      executeRequested,
      queueExecutionEnabled,
      clientProvidedIdempotency,
      requestBodyMaxBytes: limits.maxBodyBytes,
      rateLimitPerMinute: limits.rateLimitPerMinute,
      rateLimitAccepted: rateLimit.ok,
      wouldQueue: Boolean(queuedRun)
    },
    checks,
    notes: [
      queuedRun ? "Workflow was queued. Process stages with a scoped worker or worker pool." : "No workflow was queued by this request.",
      "This endpoint accepts registered project ids only; it does not accept project filesystem paths.",
      "Queue execution remains disabled unless server mode, token/OIDC auth, explicit execution, and the queue gate are all enabled."
    ]
  };
  await safeAppendServerRequestAuditEvent(buildServerRequestAuditEvent({
    request,
    payload,
    report,
    auth,
    rateLimit
  }));
  return report;
}

async function findServerQueueRunByIdempotency(input: {
  projectId: string;
  projectRootUri: string;
  workflowId: string;
  idempotencyKey: string;
}): Promise<null | { runId: string; projectId: string; workflowId: string; tasks: number }> {
  const runs = await listWorkflowRunsForProject({ projectRootUri: input.projectRootUri, limit: 500 });
  const existing = runs.find((run) =>
    run.workflowId === input.workflowId &&
    stringValue(run.evaluationMetadata?.source) === "server-queue" &&
    stringValue(run.evaluationMetadata?.idempotencyKey) === input.idempotencyKey
  );
  if (!existing) return null;
  const details = await getWorkflowRunDetails(existing.id);
  return {
    runId: existing.id,
    projectId: input.projectId,
    workflowId: existing.workflowId,
    tasks: details.tasks.length
  };
}

function validateServerMutationAuth(request: http.IncomingMessage): { ok: true; method: string } | { ok: false; method: string; error: string } {
  const authMode = process.env.AGENTFLOW_SERVER_AUTH?.trim() || "token";
  if (authMode === "oidc-proxy") {
    const actor = firstHeader(request.headers["x-agentflow-actor"] ?? request.headers["x-forwarded-email"]);
    return actor
      ? { ok: true, method: "oidc-proxy" }
      : { ok: false, method: "oidc-proxy", error: "OIDC proxy auth requires x-agentflow-actor or x-forwarded-email." };
  }
  const expectedToken = process.env.AGENTFLOW_SERVER_TOKEN?.trim();
  if (!expectedToken) {
    return { ok: false, method: "bearer-token", error: "AGENTFLOW_SERVER_TOKEN is required for server mutation endpoints." };
  }
  const authorization = firstHeader(request.headers.authorization);
  const token = authorization?.startsWith("Bearer ") ? authorization.slice("Bearer ".length).trim() : "";
  if (!token || token !== expectedToken) {
    return { ok: false, method: "bearer-token", error: "Bearer token is missing or invalid." };
  }
  return { ok: true, method: "bearer-token" };
}

function firstHeader(value: string | string[] | undefined): string | null {
  if (Array.isArray(value)) return value[0] ?? null;
  return value ?? null;
}

function serverRequestAuditLogPath(): string {
  const configured = process.env.AGENTFLOW_SERVER_REQUEST_LOG?.trim();
  return configured ? path.resolve(process.cwd(), configured) : defaultServerRequestAuditLogPath;
}

function hashAuditValue(value: string | null | undefined): string | null {
  const normalized = value?.trim();
  return normalized ? stableHash(normalized).slice(0, 16) : null;
}

function finiteNumber(value: number): number | null {
  return Number.isFinite(value) ? value : null;
}

function requestContentLength(request: http.IncomingMessage): number | null {
  const value = firstHeader(request.headers["content-length"]);
  if (!value) return null;
  const parsed = Number.parseInt(value, 10);
  return Number.isFinite(parsed) ? parsed : null;
}

function serverAuditErrorCode(message: string): string {
  const normalized = message.toLowerCase();
  if (normalized.includes("exceeds")) return "body_too_large";
  if (normalized.includes("json") || normalized.includes("parse") || normalized.includes("unexpected")) return "invalid_json";
  return "request_error";
}

function buildServerRequestAuditEvent(input: {
  request: http.IncomingMessage;
  payload: Record<string, unknown>;
  report: ServerQueueReport;
  auth: ReturnType<typeof validateServerMutationAuth>;
  rateLimit: ReturnType<typeof checkServerQueueRateLimit>;
}): ServerRequestAuditEvent {
  const task = stringValue(input.payload.task) ?? "";
  return {
    kind: "agentflow_server_request_audit_event",
    version: 1,
    generatedAt: input.report.generatedAt,
    requestId: input.report.envelope.requestId,
    method: input.request.method ?? "UNKNOWN",
    path: "/api/server-queue",
    status: input.report.status,
    dryRun: input.report.dryRun,
    executeRequested: input.report.controls.executeRequested,
    projectId: input.report.envelope.projectId || null,
    projectRootHash: hashAuditValue(input.report.route?.projectRootUri),
    workflowId: input.report.envelope.workflow || null,
    taskHash: hashAuditValue(task),
    taskBytes: Buffer.byteLength(task, "utf8"),
    actorHash: hashAuditValue(input.report.envelope.actor),
    actorRole: input.report.envelope.actorRole || null,
    auth: {
      method: input.auth.method,
      accepted: input.auth.ok,
      errorCode: input.auth.ok ? null : serverAuditErrorCode(input.auth.error)
    },
    rateLimit: {
      accepted: input.rateLimit.ok,
      keyHash: hashAuditValue(input.rateLimit.key),
      limit: finiteNumber(input.rateLimit.limit),
      remaining: finiteNumber(input.rateLimit.remaining),
      resetAt: input.rateLimit.resetAt
    },
    idempotencyKeyHash: hashAuditValue(input.report.envelope.idempotencyKey),
    clientProvidedIdempotency: input.report.controls.clientProvidedIdempotency,
    queuedRunId: input.report.queuedRun?.runId ?? null,
    reusedRun: input.report.queuedRun?.reused ?? null,
    bodyBytes: requestContentLength(input.request),
    remoteHash: hashAuditValue(input.request.socket.remoteAddress),
    originHash: hashAuditValue(firstHeader(input.request.headers.origin)),
    userAgentHash: hashAuditValue(firstHeader(input.request.headers["user-agent"])),
    checks: input.report.checks.map((check) => ({ label: check.label, status: check.status }))
  };
}

function buildServerApprovalPreviewAuditEvent(input: {
  request: http.IncomingMessage;
  report: ServerApprovalPreviewReport;
  auth: ReturnType<typeof validateServerMutationAuth>;
}): ServerRequestAuditEvent {
  return {
    kind: "agentflow_server_request_audit_event",
    version: 1,
    generatedAt: input.report.generatedAt,
    requestId: input.report.envelope.requestId,
    method: input.request.method ?? "UNKNOWN",
    path: "/api/server-approval-preview",
    status: input.report.status,
    dryRun: true,
    executeRequested: input.report.envelope.decision === "execute" || input.report.envelope.decision === "approve-and-execute",
    projectId: input.report.envelope.projectId || null,
    projectRootHash: input.report.approval?.projectRootHash ?? null,
    workflowId: input.report.approval?.workflowId ?? null,
    taskHash: hashAuditValue(input.report.envelope.approvalId),
    taskBytes: Buffer.byteLength(input.report.envelope.approvalId, "utf8"),
    actorHash: hashAuditValue(input.report.envelope.actor),
    actorRole: input.report.envelope.actorRole || null,
    auth: {
      method: input.auth.method,
      accepted: input.auth.ok,
      errorCode: input.auth.ok ? null : serverAuditErrorCode(input.auth.error)
    },
    rateLimit: {
      accepted: null,
      keyHash: null,
      limit: null,
      remaining: null,
      resetAt: null
    },
    idempotencyKeyHash: hashAuditValue(input.report.envelope.idempotencyKey),
    clientProvidedIdempotency: input.report.controls.idempotencyProvided,
    queuedRunId: input.report.approval?.runId ?? null,
    reusedRun: null,
    bodyBytes: requestContentLength(input.request),
    remoteHash: hashAuditValue(input.request.socket.remoteAddress),
    originHash: hashAuditValue(firstHeader(input.request.headers.origin)),
    userAgentHash: hashAuditValue(firstHeader(input.request.headers["user-agent"])),
    checks: input.report.checks.map((check) => ({ label: check.label, status: check.status }))
  };
}

function buildServerApprovalActionAuditEvent(input: {
  request: http.IncomingMessage;
  report: ServerApprovalActionReport;
  auth: ReturnType<typeof validateServerMutationAuth>;
  rateLimit: ReturnType<typeof checkServerQueueRateLimit>;
}): ServerRequestAuditEvent {
  return {
    kind: "agentflow_server_request_audit_event",
    version: 1,
    generatedAt: input.report.generatedAt,
    requestId: input.report.envelope.requestId,
    method: input.request.method ?? "UNKNOWN",
    path: "/api/server-approval-action",
    status: input.report.status,
    dryRun: input.report.dryRun,
    executeRequested: input.report.controls.executeRequested,
    projectId: input.report.envelope.projectId || null,
    projectRootHash: input.report.approval?.projectRootHash ?? null,
    workflowId: input.report.approval?.workflowId ?? null,
    taskHash: hashAuditValue(input.report.envelope.approvalId),
    taskBytes: Buffer.byteLength(input.report.envelope.approvalId, "utf8"),
    actorHash: hashAuditValue(input.report.envelope.actor),
    actorRole: input.report.envelope.actorRole || null,
    auth: {
      method: input.auth.method,
      accepted: input.auth.ok,
      errorCode: input.auth.ok ? null : serverAuditErrorCode(input.auth.error)
    },
    rateLimit: {
      accepted: input.rateLimit.ok,
      keyHash: hashAuditValue(input.rateLimit.key),
      limit: finiteNumber(input.rateLimit.limit),
      remaining: finiteNumber(input.rateLimit.remaining),
      resetAt: input.rateLimit.resetAt
    },
    idempotencyKeyHash: hashAuditValue(input.report.envelope.idempotencyKey),
    clientProvidedIdempotency: input.report.controls.clientProvidedIdempotency,
    queuedRunId: input.report.approval?.runId ?? null,
    reusedRun: null,
    bodyBytes: requestContentLength(input.request),
    remoteHash: hashAuditValue(input.request.socket.remoteAddress),
    originHash: hashAuditValue(firstHeader(input.request.headers.origin)),
    userAgentHash: hashAuditValue(firstHeader(input.request.headers["user-agent"])),
    checks: input.report.checks.map((check) => ({ label: check.label, status: check.status }))
  };
}

function buildServerRequestBodyErrorAuditEvent(request: http.IncomingMessage, error: unknown, requestPath = "/api/server-queue"): ServerRequestAuditEvent {
  const generatedAt = new Date().toISOString();
  const errorMessage = error instanceof Error ? error.message : String(error);
  return {
    kind: "agentflow_server_request_audit_event",
    version: 1,
    generatedAt,
    requestId: `req_body_${stableHash([generatedAt, request.method, request.url, requestContentLength(request)]).slice(0, 16)}`,
    method: request.method ?? "UNKNOWN",
    path: requestPath,
    status: "rejected",
    dryRun: true,
    executeRequested: false,
    projectId: null,
    projectRootHash: null,
    workflowId: null,
    taskHash: null,
    taskBytes: 0,
    actorHash: null,
    actorRole: null,
    auth: {
      method: process.env.AGENTFLOW_SERVER_AUTH?.trim() || "token",
      accepted: false,
      errorCode: serverAuditErrorCode(errorMessage)
    },
    rateLimit: {
      accepted: null,
      keyHash: null,
      limit: null,
      remaining: null,
      resetAt: null
    },
    idempotencyKeyHash: null,
    clientProvidedIdempotency: false,
    queuedRunId: null,
    reusedRun: null,
    bodyBytes: requestContentLength(request),
    remoteHash: hashAuditValue(request.socket.remoteAddress),
    originHash: hashAuditValue(firstHeader(request.headers.origin)),
    userAgentHash: hashAuditValue(firstHeader(request.headers["user-agent"])),
    checks: [{ label: "Request body", status: "fail" }]
  };
}

async function safeAppendServerRequestAuditEvent(event: ServerRequestAuditEvent): Promise<void> {
  try {
    const logPath = serverRequestAuditLogPath();
    await fs.mkdir(path.dirname(logPath), { recursive: true });
    await fs.appendFile(logPath, `${JSON.stringify(event)}\n`, "utf8");
  } catch (error) {
    console.error(`WARNING: failed to write server request audit log: ${error instanceof Error ? error.message : String(error)}`);
  }
}

async function loadServerRequestAuditLog(limit = 50): Promise<ServerRequestAuditReport> {
  const logPath = serverRequestAuditLogPath();
  const normalizedLimit = parsePositiveInteger(String(limit), 50);
  let raw = "";
  try {
    raw = await fs.readFile(logPath, "utf8");
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error;
  }
  const lines = raw.split(/\r?\n/).filter((line) => line.trim());
  const events: ServerRequestAuditEvent[] = [];
  let invalidLines = 0;
  for (const line of lines) {
    try {
      const parsed = JSON.parse(line) as ServerRequestAuditEvent;
      if (parsed?.kind === "agentflow_server_request_audit_event") events.push(parsed);
      else invalidLines += 1;
    } catch {
      invalidLines += 1;
    }
  }
  const latest = events.slice(-normalizedLimit).reverse();
  const statusCounts: Record<string, number> = {};
  const authCounts: Record<string, number> = {};
  for (const event of events) {
    statusCounts[event.status] = (statusCounts[event.status] ?? 0) + 1;
    const authKey = `${event.auth.method}:${event.auth.accepted ? "accepted" : "rejected"}`;
    authCounts[authKey] = (authCounts[authKey] ?? 0) + 1;
  }
  return {
    kind: "agentflow_server_request_audit_report",
    generatedAt: new Date().toISOString(),
    logPath,
    limit: normalizedLimit,
    totalRead: events.length,
    invalidLines,
    latestAt: events.at(-1)?.generatedAt ?? null,
    statusCounts,
    authCounts,
    rateLimited: events.filter((event) => event.rateLimit.accepted === false).length,
    queued: events.filter((event) => event.status === "queued").length,
    blocked: events.filter((event) => event.status === "blocked" || event.status === "rejected").length,
    dryRuns: events.filter((event) => event.dryRun).length,
    events: latest,
    notes: [
      "This log is redacted by design: actor, task, idempotency key, network address, origin, user-agent, and local project roots are stored as hashes.",
      "It currently records the governed /api/server-queue mutation surface.",
      "Use this as request evidence alongside per-run action receipts."
    ]
  };
}

function formatServerRequestAuditReport(report: ServerRequestAuditReport): string {
  return [
    `Server request audit log (${report.generatedAt})`,
    `Path: ${report.logPath}`,
    `Events: ${report.totalRead}`,
    `Latest: ${report.latestAt ?? "none"}`,
    `Invalid lines skipped: ${report.invalidLines}`,
    "",
    "Summary:",
    `- queued: ${report.queued}`,
    `- blocked/rejected: ${report.blocked}`,
    `- dry runs: ${report.dryRuns}`,
    `- rate limited: ${report.rateLimited}`,
    `- status counts: ${formatInlineCounts(report.statusCounts) || "none"}`,
    `- auth counts: ${formatInlineCounts(report.authCounts) || "none"}`,
    "",
    "Recent events:",
    ...(report.events.length ? report.events.map((event) => `- ${event.generatedAt} ${event.status.toUpperCase()} ${event.method} ${event.path} project=${event.projectId ?? "n/a"} workflow=${event.workflowId ?? "n/a"} execute=${event.executeRequested ? "yes" : "no"} auth=${event.auth.method}:${event.auth.accepted ? "pass" : event.auth.errorCode ?? "fail"} rateLimit=${event.rateLimit.accepted === null ? "n/a" : event.rateLimit.accepted ? "pass" : "fail"} run=${event.queuedRunId ?? "none"}`) : ["- No server request audit events found."]),
    "",
    "Notes:",
    ...report.notes.map((note) => `- ${note}`)
  ].join("\n");
}

function formatArtifactLifecycleActionPlan(plan: ArtifactLifecycleActionPlan): string[] {
  return [
    "",
    `Dry-run ${plan.action} plan:`,
    `- Candidates: ${plan.totalCandidates}`,
    `- Estimated recoverable: ${formatBytes(plan.estimatedBytesRecoverable)}`,
    `- Criteria: source=${plan.criteria.policySource} minAgeDays=${plan.criteria.minAgeDays} minBytes=${plan.criteria.minBytes} includeAudit=${plan.criteria.includeAudit} legalHold=${plan.criteria.legalHold} requireApproval=${plan.criteria.requireApproval}`,
    ...plan.notes.map((note) => `- ${note}`),
    ...plan.candidates.slice(0, 20).map((candidate) => `- ${candidate.artifactId} ${candidate.uri} (${formatBytes(candidate.contentBytes)}): ${candidate.reason} [receipt=${candidate.receiptPreview.actionType}]`)
  ];
}

function artifactAgeBucket(value: string): string {
  const ageMs = Date.now() - Date.parse(value);
  if (!Number.isFinite(ageMs) || ageMs < 0) return "unknown";
  const days = ageMs / 86_400_000;
  if (days <= 1) return "0-1d";
  if (days <= 7) return "2-7d";
  if (days <= 30) return "8-30d";
  if (days <= 90) return "31-90d";
  return "90d+";
}

function artifactLifecycleHint(artifact: DashboardArtifactLifecycleRow, ageBucket: string): string {
  if (artifact.kind === "action_approval" || artifact.kind === "run_feedback" || artifact.kind === "command_output" || artifact.kind === "file_write") {
    return "retain for audit";
  }
  if (artifact.runStatus === "failed" || artifact.runStatus === "running" || artifact.runStatus === "queued") {
    return "retain until run reviewed";
  }
  if ((ageBucket === "31-90d" || ageBucket === "90d+") && artifact.contentBytes > 20_000) {
    return "candidate for future prune plan";
  }
  return "retain by default";
}

function buildArtifactLifecycleHints(artifacts: ArtifactLifecycleReport["recentArtifacts"], estimatedBytes: number, limit: number): string[] {
  const hints: string[] = [];
  const futurePruneCandidates = artifacts.filter((artifact) => artifact.lifecycleHint === "candidate for future prune plan");
  const failedRunArtifacts = artifacts.filter((artifact) => artifact.runStatus === "failed").length;
  const auditArtifacts = artifacts.filter((artifact) => artifact.lifecycleHint === "retain for audit").length;
  if (artifacts.length === limit) hints.push("Report hit the inspection limit; increase --limit before making lifecycle decisions.");
  if (futurePruneCandidates.length) hints.push(`${futurePruneCandidates.length} older large artifact(s) look like candidates for a future dry-run prune plan.`);
  if (failedRunArtifacts) hints.push(`${failedRunArtifacts} artifact(s) belong to failed runs; review failures before pruning any related evidence.`);
  if (auditArtifacts) hints.push(`${auditArtifacts} artifact(s) are audit evidence and should be retained unless project retention policy says otherwise.`);
  if (estimatedBytes === 0) hints.push("No artifact storage was found in the inspected window.");
  return hints;
}

function buildArtifactPrunePlan(artifacts: ArtifactLifecycleReport["recentArtifacts"], criteria: ArtifactPrunePlan["criteria"]): ArtifactPrunePlan {
  if (criteria.legalHold) {
    return {
      mode: "dry-run",
      generatedAt: new Date().toISOString(),
      criteria,
      totalCandidates: 0,
      estimatedBytesRecoverable: 0,
      approvalRequired: criteria.requireApproval,
      notes: [
        "Dry run only. This plan does not delete, archive, or mutate artifacts.",
        "Project legal hold is enabled; prune candidates are suppressed."
      ],
      candidates: []
    };
  }
  const candidates = artifacts.flatMap((artifact) => {
    const ageDays = artifactAgeDays(artifact.createdAt);
    const reason = artifactPruneReason(artifact, ageDays, criteria);
    if (!reason) return [];
    return [{
      artifactId: artifact.id,
      uri: artifact.uri,
      runId: artifact.runId,
      taskId: artifact.taskId,
      projectName: artifact.projectName,
      projectRootUri: artifact.projectRootUri,
      workflowId: artifact.workflowId,
      runStatus: artifact.runStatus,
      kind: artifact.kind,
      contentBytes: artifact.contentBytes,
      createdAt: artifact.createdAt,
      ageDays,
      reason,
      receiptPreview: {
        actionType: "artifact_prune_requested" as const,
        target: artifact.uri,
        summary: `Would request pruning ${artifact.kind} artifact ${artifact.id}`,
        metadata: {
          mode: "dry-run" as const,
          action: "prune" as const,
          artifactId: artifact.id,
          runId: artifact.runId,
          taskId: artifact.taskId,
          kind: artifact.kind,
          contentBytes: artifact.contentBytes,
          reason
        }
      }
    }];
  });
  const estimatedBytesRecoverable = candidates.reduce((sum, candidate) => sum + candidate.contentBytes + candidate.uri.length, 0);
  const auditCount = artifacts.filter(isAuditArtifact).length;
  const notes = [
    "Dry run only. This plan does not delete, archive, or mutate artifacts.",
    "Any future prune execution must recheck current storage state, project policy, and approval requirements.",
    criteria.includeAudit ? "Audit artifacts were allowed into candidate selection by request." : `${auditCount} audit artifact(s) were excluded from candidate selection.`
  ];
  if (!candidates.length) {
    notes.push("No artifacts matched the current prune criteria.");
  }
  return {
    mode: "dry-run",
    generatedAt: new Date().toISOString(),
    criteria,
    totalCandidates: candidates.length,
    estimatedBytesRecoverable,
    approvalRequired: criteria.requireApproval,
    notes,
    candidates
  };
}

function buildArtifactArchivePlan(artifacts: ArtifactLifecycleReport["recentArtifacts"], criteria: ArtifactPrunePlan["criteria"]): ArtifactLifecycleActionPlan {
  if (criteria.legalHold) {
    return emptyArtifactLifecycleActionPlan("archive", criteria, "Project legal hold is enabled; archive candidates are suppressed.");
  }
  const candidates = artifacts.flatMap((artifact) => {
    const ageDays = artifactAgeDays(artifact.createdAt);
    const reason = artifactPruneReason(artifact, ageDays, criteria);
    if (!reason) return [];
    return [artifactLifecycleCandidate(artifact, ageDays, reason.replace("belongs to", "is ready for archive review and belongs to"), "archive")];
  });
  return {
    mode: "dry-run",
    action: "archive",
    generatedAt: new Date().toISOString(),
    criteria,
    totalCandidates: candidates.length,
    estimatedBytesRecoverable: candidates.reduce((sum, candidate) => sum + candidate.contentBytes + candidate.uri.length, 0),
    approvalRequired: criteria.requireApproval,
    notes: [
      "Dry run only. This plan does not archive, move, delete, or mutate artifacts.",
      "Approved archive execution copies artifacts into archived snapshots, records lifecycle receipts, and preserves restore metadata.",
      criteria.includeAudit ? "Audit artifacts were allowed into archive candidate selection by request." : `${artifacts.filter(isAuditArtifact).length} audit artifact(s) were excluded from archive candidate selection.`,
      ...(candidates.length ? [] : ["No artifacts matched the current archive criteria."])
    ],
    candidates
  };
}

async function buildArtifactRestorePlan(artifacts: ArtifactLifecycleReport["recentArtifacts"], criteria: ArtifactPrunePlan["criteria"]): Promise<ArtifactLifecycleActionPlan> {
  if (criteria.legalHold) {
    return emptyArtifactLifecycleActionPlan("restore", criteria, "Project legal hold is enabled; restore candidates are suppressed.");
  }
  const archivedArtifacts = artifacts.filter((artifact) => artifact.kind === "archived_artifact");
  const candidates: ArtifactLifecycleActionPlan["candidates"] = [];
  for (const artifact of archivedArtifacts) {
    const fullArtifact = await getArtifactByUri(artifact.uri);
    if (!fullArtifact || fullArtifact.content.originalActionType !== "artifact_archive") continue;
    const restoreMetadata = objectFromRecord(fullArtifact.content, "restoreMetadata");
    const target = stringFromRecord(restoreMetadata, "originalUri") || stringFromRecord(fullArtifact.content, "target");
    if (!target) continue;
    const ageDays = artifactAgeDays(artifact.createdAt);
    const reason = `Archived artifact snapshot can be reviewed for restore target ${target}.`;
    candidates.push({
      artifactId: artifact.id,
      uri: target,
      runId: artifact.runId,
      taskId: artifact.taskId,
      projectName: artifact.projectName,
      projectRootUri: artifact.projectRootUri,
      workflowId: artifact.workflowId,
      runStatus: artifact.runStatus,
      kind: "archived_artifact",
      contentBytes: artifact.contentBytes,
      createdAt: artifact.createdAt,
      ageDays,
      reason,
      receiptPreview: artifactLifecycleReceiptPreview({
        action: "restore",
        artifactId: artifact.id,
        uri: target,
        runId: artifact.runId,
        taskId: artifact.taskId,
        kind: "archived_artifact",
        contentBytes: artifact.contentBytes,
        reason
      })
    });
  }
  return {
    mode: "dry-run",
    action: "restore",
    generatedAt: new Date().toISOString(),
    criteria,
    totalCandidates: candidates.length,
    estimatedBytesRecoverable: 0,
    approvalRequired: criteria.requireApproval,
    notes: [
      "Dry run only. This plan does not restore, move, delete, or mutate artifacts.",
      "Restore candidates come only from archived artifact snapshots.",
      ...(candidates.length ? [] : ["No archived artifact snapshots were found in the inspected artifact window."])
    ],
    candidates
  };
}

function emptyArtifactLifecycleActionPlan(action: "archive" | "restore", criteria: ArtifactPrunePlan["criteria"], note: string): ArtifactLifecycleActionPlan {
  return {
    mode: "dry-run",
    action,
    generatedAt: new Date().toISOString(),
    criteria,
    totalCandidates: 0,
    estimatedBytesRecoverable: 0,
    approvalRequired: criteria.requireApproval,
    notes: [
      "Dry run only. This plan does not mutate artifacts.",
      note
    ],
    candidates: []
  };
}

function artifactLifecycleCandidate(
  artifact: ArtifactLifecycleReport["recentArtifacts"][number],
  ageDays: number | null,
  reason: string,
  action: ArtifactLifecycleAction
): ArtifactLifecycleActionPlan["candidates"][number] {
  return {
    artifactId: artifact.id,
    uri: artifact.uri,
    runId: artifact.runId,
    taskId: artifact.taskId,
    projectName: artifact.projectName,
    projectRootUri: artifact.projectRootUri,
    workflowId: artifact.workflowId,
    runStatus: artifact.runStatus,
    kind: artifact.kind,
    contentBytes: artifact.contentBytes,
    createdAt: artifact.createdAt,
    ageDays,
    reason,
    receiptPreview: artifactLifecycleReceiptPreview({
      action,
      artifactId: artifact.id,
      uri: artifact.uri,
      runId: artifact.runId,
      taskId: artifact.taskId,
      kind: artifact.kind,
      contentBytes: artifact.contentBytes,
      reason
    })
  };
}

function artifactLifecycleReceiptPreview(input: {
  action: ArtifactLifecycleAction;
  artifactId: string;
  uri: string;
  runId: string;
  taskId: string | null;
  kind: string;
  contentBytes: number;
  reason: string;
}): ArtifactLifecycleReceiptPreview {
  const requestedActionType: Record<ArtifactLifecycleAction, ArtifactLifecycleRequestedActionType> = {
    prune: "artifact_prune_requested",
    archive: "artifact_archive_requested",
    restore: "artifact_restore_requested"
  };
  return {
    actionType: requestedActionType[input.action],
    target: input.uri,
    summary: `Would request ${input.action} for ${input.kind} artifact ${input.artifactId}`,
    metadata: {
      mode: "dry-run",
      action: input.action,
      artifactId: input.artifactId,
      runId: input.runId,
      taskId: input.taskId,
      kind: input.kind,
      contentBytes: input.contentBytes,
      reason: input.reason
    }
  };
}

function artifactPruneReason(artifact: ArtifactLifecycleReport["recentArtifacts"][number], ageDays: number | null, criteria: ArtifactPrunePlan["criteria"]): string | null {
  if (!criteria.includeAudit && isAuditArtifact(artifact)) return null;
  if (artifact.runStatus !== "completed" && artifact.runStatus !== "dismissed" && artifact.runStatus !== "cancelled") return null;
  if (ageDays === null || ageDays < criteria.minAgeDays) return null;
  if (artifact.contentBytes < criteria.minBytes) return null;
  return `${artifact.kind} is ${ageDays} day(s) old, ${formatBytes(artifact.contentBytes)}, and belongs to a ${artifact.runStatus} run.`;
}

function artifactAgeDays(value: string): number | null {
  const ageMs = Date.now() - Date.parse(value);
  if (!Number.isFinite(ageMs) || ageMs < 0) return null;
  return Math.floor(ageMs / 86_400_000);
}

function isAuditArtifact(artifact: { kind: string }): boolean {
  return artifact.kind === "action_approval" || artifact.kind === "run_feedback" || artifact.kind === "command_output" || artifact.kind === "file_write";
}

async function loadDashboardEvaluations(limit = 250): Promise<DashboardEvaluationSuite[]> {
  const runs = (await listWorkflowRuns(limit)).filter((run) =>
    typeof run.evaluationMetadata?.suiteId === "string"
  );
  const evaluated: DashboardEvaluationRun[] = [];
  for (const run of runs) {
    const metadata = run.evaluationMetadata ?? {};
    const report = await loadCostQualityReport(run.id);
    if (!report) {
      continue;
    }
    const suiteId = stringValue(metadata.suiteId);
    const caseId = stringValue(metadata.caseId);
    const variantId = stringValue(metadata.variantId);
    if (!suiteId || !caseId || !variantId) {
      continue;
    }
    evaluated.push({
      runId: run.id,
      suiteId,
      suiteName: stringValue(metadata.suiteName) ?? suiteId,
      caseId,
      variantId,
      workflowId: run.workflowId,
      provider: run.providerOverride ?? Object.keys(report.providerMix)[0] ?? "unknown",
      modelTier: run.modelTierOverride ?? Object.keys(report.modelTierMix)[0] ?? "unknown",
      status: run.status,
      averageQuality: report.averageQuality,
      totalLatencyMs: report.totalLatencyMs,
      fallbackCount: report.fallbackCount,
      estimatedCostMix: report.estimatedCostMix,
      feedback: report.feedback.latest?.rating ?? null,
      startedAt: run.startedAt
    });
  }

  const suites = new Map<string, DashboardEvaluationRun[]>();
  for (const run of evaluated) {
    const selected = suites.get(run.suiteId) ?? [];
    selected.push(run);
    suites.set(run.suiteId, selected);
  }
  return [...suites.entries()].map(([id, suiteRuns]): DashboardEvaluationSuite => {
    const variantIds = [...new Set(suiteRuns.map((run) => run.variantId))];
    const variants = variantIds.map((variantId): DashboardEvaluationVariant => {
      const selected = suiteRuns.filter((run) => run.variantId === variantId);
      const scored = selected.filter((run) => run.averageQuality !== null);
      return {
        id: variantId,
        provider: selected[0]?.provider ?? "unknown",
        modelTier: selected[0]?.modelTier ?? "unknown",
        runs: selected.length,
        completed: selected.filter((run) => run.status === "completed").length,
        averageQuality: scored.length
          ? Math.round(scored.reduce((sum, run) => sum + (run.averageQuality ?? 0), 0) / scored.length * 1000) / 1000
          : null,
        averageLatencyMs: selected.length
          ? Math.round(selected.reduce((sum, run) => sum + run.totalLatencyMs, 0) / selected.length)
          : null,
        fallbackRate: Math.round(selected.reduce((sum, run) => sum + run.fallbackCount, 0) / Math.max(1, selected.length) * 1000) / 1000,
        estimatedCostMix: mergeCounts(selected.map((run) => run.estimatedCostMix)),
        feedbackCounts: countStrings(selected.flatMap((run) => run.feedback ? [run.feedback] : []))
      };
    }).sort((a, b) =>
      b.completed / Math.max(1, b.runs) - a.completed / Math.max(1, a.runs) ||
      (b.averageQuality ?? -1) - (a.averageQuality ?? -1) ||
      a.fallbackRate - b.fallbackRate ||
      (a.averageLatencyMs ?? Number.MAX_SAFE_INTEGER) - (b.averageLatencyMs ?? Number.MAX_SAFE_INTEGER)
    );
    return {
      id,
      name: suiteRuns[0]?.suiteName ?? id,
      workflowId: suiteRuns[0]?.workflowId ?? "unknown",
      runs: suiteRuns.sort((a, b) => b.startedAt.localeCompare(a.startedAt)),
      variants,
      leader: variants[0]?.id ?? null,
      latestAt: suiteRuns.map((run) => run.startedAt).sort().at(-1) ?? ""
    };
  }).sort((a, b) => b.latestAt.localeCompare(a.latestAt));
}

function mergeCounts(items: Record<string, number>[]): Record<string, number> {
  const result: Record<string, number> = {};
  for (const item of items) {
    for (const [key, value] of Object.entries(item)) {
      result[key] = (result[key] ?? 0) + value;
    }
  }
  return result;
}

function countStrings(items: string[]): Record<string, number> {
  return mergeCounts(items.map((item) => ({ [item]: 1 })));
}

async function loadDashboardUsageSummary(runs: DashboardRunStatus[], input: { includeMock: boolean }): Promise<DashboardUsageSummary> {
  const projectTokenTotals = new Map<string, number>();
  const metricRuns: DashboardRunStatus[] = [];
  const metricStages: CostQualityReport["stages"] = [];
  const estimates: RunUsageEstimate[] = [];
  let mockRunsExcluded = 0;
  let mockStagesExcluded = 0;

  const loadedRuns = await Promise.all(runs.map(async (run) => {
    const [details, artifacts] = await Promise.all([
      getWorkflowRunDetails(run.id),
      listArtifacts({ runId: run.id })
    ]);
    if (!details.run) return null;
    const report = buildCostQualityReport({
      run: details.run,
      tasks: details.tasks,
      receipts: details.receipts,
      artifacts
    });
    return { run: details.run, artifacts, report };
  }));

  const includedRuns = loadedRuns.filter((loaded): loaded is NonNullable<typeof loaded> => loaded !== null);
  const runEstimates = await Promise.all(includedRuns.map(async ({ run, artifacts, report }) => {
    const mockStages = report.stages.filter((stage) => stage.providerId === "mock");
    const realStages = report.stages.filter((stage) => stage.providerId !== "mock");
    const mockOnlyRun = report.routedStages > 0 && realStages.length === 0;
    if (!input.includeMock && mockOnlyRun) {
      return { run, report, mockStages, realStages, mockOnlyRun, estimate: null };
    }
    const estimate = await buildRunUsageEstimate({
      run,
      artifacts,
      routedStages: input.includeMock ? report.routedStages : Math.max(1, realStages.length),
      projectTokenTotals
    });
    return { run, report, mockStages, realStages, mockOnlyRun, estimate };
  }));

  for (const loaded of runEstimates) {
    if (loaded.mockOnlyRun && !input.includeMock) {
      mockRunsExcluded += 1;
      mockStagesExcluded += loaded.mockStages.length;
      continue;
    }
    metricRuns.push(loaded.run);
    metricStages.push(...(input.includeMock ? loaded.report.stages : loaded.realStages));
    if (!input.includeMock) mockStagesExcluded += loaded.mockStages.length;
    if (loaded.estimate) estimates.push(loaded.estimate);
  }

  const totalLatencyMs = metricStages.reduce((sum, stage) => sum + (stage.latencyMs ?? 0), 0);
  const latencyStages = metricStages.filter((stage) => stage.latencyMs !== null).length;
  const durations = estimates
    .map((estimate) => estimate.runDurationMs)
    .filter((duration): duration is number => duration !== null);
  const estimatedPromptTokens = estimates.reduce((sum, estimate) => sum + estimate.estimatedPromptTokens, 0);
  const estimatedBaselineTokens = estimates.reduce((sum, estimate) => sum + estimate.estimatedBaselineTokens, 0);
  const estimatedTokensSaved = estimates.reduce((sum, estimate) => sum + estimate.estimatedTokensSaved, 0);

  return {
    includeMock: input.includeMock,
    partial: false,
    note: null,
    runsAnalyzed: metricRuns.length,
    completedRuns: metricRuns.filter((run) => run.status === "completed").length,
    failedRuns: metricRuns.filter((run) => run.status === "failed").length,
    queuedRuns: metricRuns.filter((run) => run.status === "queued").length,
    runningRuns: metricRuns.filter((run) => run.status === "running").length,
    mockRunsExcluded,
    mockStagesExcluded,
    routedStages: metricStages.length,
    totalLatencyMs,
    averageLatencyMs: latencyStages ? Math.round(totalLatencyMs / latencyStages) : null,
    averageRunDurationMs: durations.length ? Math.round(durations.reduce((sum, duration) => sum + duration, 0) / durations.length) : null,
    estimatedPromptTokens,
    estimatedBaselineTokens,
    estimatedTokensSaved,
    tokenReductionPercent: estimatedBaselineTokens > 0 ? Math.round((estimatedTokensSaved / estimatedBaselineTokens) * 100) : null,
    providerMix: countDashboardStages(metricStages, (stage) => stage.providerId),
    costMix: countDashboardStages(metricStages, (stage) => stage.estimatedCostTier),
    modelTierMix: countDashboardStages(metricStages, (stage) => stage.modelTier),
    byoSavingsStages: metricStages.filter((stage) =>
      ["local", "byo", "openai-compatible"].includes(stage.providerId) &&
      ["low", "medium", "none"].includes(stage.estimatedCostTier)
    ).length
  };
}

function fallbackDashboardUsageSummary(runs: DashboardRunStatus[], input: { includeMock: boolean; note: string }): DashboardUsageSummary {
  return {
    includeMock: input.includeMock,
    partial: true,
    note: input.note,
    runsAnalyzed: runs.length,
    completedRuns: runs.filter((run) => run.status === "completed").length,
    failedRuns: runs.filter((run) => run.status === "failed").length,
    queuedRuns: runs.filter((run) => run.status === "queued").length,
    runningRuns: runs.filter((run) => run.status === "running").length,
    mockRunsExcluded: 0,
    mockStagesExcluded: 0,
    routedStages: 0,
    totalLatencyMs: 0,
    averageLatencyMs: null,
    averageRunDurationMs: null,
    estimatedPromptTokens: 0,
    estimatedBaselineTokens: 0,
    estimatedTokensSaved: 0,
    tokenReductionPercent: null,
    providerMix: {},
    costMix: {},
    modelTierMix: {},
    byoSavingsStages: 0
  };
}

async function withTimeout<T>(promise: Promise<T>, timeoutMs: number, onTimeout: () => T | Promise<T>): Promise<T> {
  let timer: NodeJS.Timeout | undefined;
  try {
    return await Promise.race([
      promise,
      new Promise<T>((resolve) => {
        timer = setTimeout(() => resolve(onTimeout()), timeoutMs);
      })
    ]);
  } finally {
    if (timer) {
      clearTimeout(timer);
    }
  }
}

async function loadDashboardProjectDetail(rootUri: string): Promise<DashboardProjectDetail | null> {
  const projects = await listProjectStorageSummaries(500);
  const project = projects.find((item) => item.rootUri === rootUri);
  if (!project) {
    return null;
  }
  const projectPath = await resolveDashboardProjectPath(rootUri);
  const [files, memory, runs, contextFiles] = await Promise.all([
    listProjectFileSummaries({ projectRootUri: rootUri, limit: 20 }),
    getLatestMemory({ projectRootUri: rootUri, limit: 8 }),
    listWorkflowRunsForProject({ projectRootUri: rootUri, limit: 12 }),
    loadDashboardProjectContextFiles(projectPath.localRootUri)
  ]);
  const config = project.config as {
    actions?: { allowed_write_paths?: string[] };
    policies?: { allow_wide_open?: boolean };
  };
  return {
    project,
    files,
    memory,
    runs,
    contextFiles,
    initialized: contextFiles.some((file) => file.relativePath === ".agent-workflow/project.yaml" && file.exists),
    allowWrites: Boolean(config.policies?.allow_wide_open || (config.actions?.allowed_write_paths?.length ?? 0) > 0)
  };
}

async function resolveDashboardProjectPath(rootUri: string): Promise<DashboardProjectPathResolution> {
  return resolveLocalProjectPath(rootUri);
}

async function loadDashboardProjectIdentityGroups(projects: DashboardProjectSummary[]): Promise<DashboardProjectIdentityGroup[]> {
  const resolutions = await Promise.all(projects.map(async (project) => ({
    project,
    resolution: await resolveDashboardProjectPath(project.rootUri)
  })));
  const grouped = new Map<string, Array<(typeof resolutions)[number]>>();
  for (const item of resolutions) {
    const key = item.resolution.localPathExists ? item.resolution.localRootUri : item.resolution.storageRootUri;
    grouped.set(key, [...(grouped.get(key) ?? []), item]);
  }
  return [...grouped.entries()]
    .map(([canonicalRootUri, items]) => {
      const projectsInGroup = items.map((item) => item.project);
      const latestRunAt = projectsInGroup
        .map((project) => project.lastRunAt)
        .filter((value): value is string => Boolean(value))
        .sort()
        .at(-1) ?? null;
      const preferred = items.find((item) => item.resolution.localRootUri === canonicalRootUri)?.project ?? projectsInGroup[0];
      const preferredResolution = items.find((item) => item.project === preferred)?.resolution ?? items[0].resolution;
      return {
        canonicalRootUri,
        primaryRootUri: preferred.rootUri,
        canonicalName: preferred.name,
        localPathExists: items.some((item) => item.resolution.localPathExists),
        source: preferredResolution.source,
        projects: projectsInGroup,
        totalRuns: projectsInGroup.reduce((sum, project) => sum + project.runCount, 0),
        totalIndexedFiles: projectsInGroup.reduce((sum, project) => sum + project.indexedFiles, 0),
        totalMemoryItems: projectsInGroup.reduce((sum, project) => sum + project.memoryItems, 0),
        activeRuns: projectsInGroup.reduce((sum, project) => sum + project.queuedRuns + project.runningRuns, 0),
        failedRuns: projectsInGroup.reduce((sum, project) => sum + project.failedRuns, 0),
        lastRunAt: latestRunAt,
        aliases: items.map((item) => ({
          rootUri: item.resolution.storageRootUri,
          mapped: item.resolution.mapped,
          source: item.resolution.source
        })).sort((left, right) => left.rootUri.localeCompare(right.rootUri))
      };
    })
    .sort((left, right) => {
      const latest = (right.lastRunAt ?? "").localeCompare(left.lastRunAt ?? "");
      return latest || right.totalRuns - left.totalRuns || left.canonicalName.localeCompare(right.canonicalName);
    });
}

function buildDashboardProjectAliasMergePlan(
  projects: DashboardProjectSummary[],
  identities: DashboardProjectIdentityGroup[]
): DashboardProjectAliasMergePlan {
  const groups = identities
    .filter((identity) => identity.projects.length > 1)
    .map((identity) => buildDashboardProjectAliasMergeGroup(identity));
  const sourceProjectCount = groups.reduce((sum, group) => sum + group.sources.length, 0);
  return {
    kind: "agentflow_project_alias_merge_plan",
    generatedAt: new Date().toISOString(),
    dryRun: true,
    identityCount: identities.length,
    projectCount: projects.length,
    candidateCount: groups.length,
    sourceProjectCount,
    groups,
    summary: groups.length
      ? [
          `${groups.length} logical project identity group(s) have duplicate registered roots.`,
          `${sourceProjectCount} source project row(s) could be consolidated into canonical targets after backup and conflict checks.`,
          "This report is dry-run only; it does not update workflow runs, indexed files, memory items, approvals, or project rows."
        ]
      : [
          "No duplicate project identity groups were found.",
          "No project alias merge is recommended right now."
        ]
  };
}

function buildDashboardProjectAliasMergeGroup(identity: DashboardProjectIdentityGroup): DashboardProjectAliasMergeGroup {
  const sortedProjects = [...identity.projects].sort((left, right) => {
    const leftPrimary = left.rootUri === identity.primaryRootUri ? 1 : 0;
    const rightPrimary = right.rootUri === identity.primaryRootUri ? 1 : 0;
    return rightPrimary - leftPrimary
      || right.runCount - left.runCount
      || right.indexedFiles - left.indexedFiles
      || (right.lastRunAt ?? "").localeCompare(left.lastRunAt ?? "")
      || left.rootUri.localeCompare(right.rootUri);
  });
  const targetProject = sortedProjects[0];
  const sourceProjects = sortedProjects.slice(1);
  const target = dashboardProjectAliasMergeProject(targetProject);
  const sources = sourceProjects.map(dashboardProjectAliasMergeProject);
  const impactedRows = {
    projectRows: sourceProjects.length,
    workflowRuns: sources.reduce((sum, project) => sum + project.runCount, 0),
    activeRuns: sources.reduce((sum, project) => sum + project.activeRuns, 0),
    failedRuns: sources.reduce((sum, project) => sum + project.failedRuns, 0),
    projectFiles: sources.reduce((sum, project) => sum + project.indexedFiles, 0),
    memoryItems: sources.reduce((sum, project) => sum + project.memoryItems, 0),
    indexedTokens: sources.reduce((sum, project) => sum + project.indexedTokens, 0),
    indirectRunArtifacts: "via workflow_runs after project_id reassignment"
  };
  const conflictWarnings = buildProjectAliasMergeWarnings(target, sources, impactedRows);
  const risk: DashboardProjectAliasMergeGroup["risk"] = impactedRows.activeRuns > 0 || conflictWarnings.length > 2
    ? "high"
    : impactedRows.projectFiles > 0 || impactedRows.memoryItems > 0
      ? "medium"
      : "low";
  return {
    canonicalRootUri: identity.canonicalRootUri,
    target,
    sources,
    impactedRows,
    risk,
    conflictWarnings,
    preflightChecks: [
      "Run storage-merge-evidence and storage-verify immediately before execution.",
      "Create a point-in-time database backup and object-storage inventory.",
      "Confirm no source project alias has queued or running workflow runs.",
      "Detect duplicate project_files.source_uri rows and preserve newer content_hash/token evidence.",
      "Keep the source root_uri values as aliases in an auditable receipt before deleting or tombstoning rows."
    ],
    rollbackOutline: [
      "Restore the database backup for a full rollback, or replay the generated mapping receipt to move project_id references back to each source project id.",
      "Recreate source project rows from the pre-merge snapshot if they were tombstoned or removed.",
      "Re-run storage-verify, project identity grouping, and a small workflow smoke test after rollback."
    ]
  };
}

function dashboardProjectAliasMergeProject(project: DashboardProjectSummary): DashboardProjectAliasMergeProject {
  return {
    id: project.id,
    name: project.name,
    rootUri: project.rootUri,
    profile: project.profile,
    indexedFiles: project.indexedFiles,
    indexedTokens: project.indexedTokens,
    memoryItems: project.memoryItems,
    runCount: project.runCount,
    completedRuns: project.completedRuns,
    failedRuns: project.failedRuns,
    activeRuns: project.queuedRuns + project.runningRuns,
    lastRunAt: project.lastRunAt
  };
}

function buildProjectAliasMergeWarnings(
  target: DashboardProjectAliasMergeProject,
  sources: DashboardProjectAliasMergeProject[],
  impactedRows: DashboardProjectAliasMergeGroup["impactedRows"]
): string[] {
  const warnings: string[] = [];
  if (impactedRows.activeRuns > 0) warnings.push("One or more source aliases have active runs; wait until they are terminal before merging.");
  if (target.indexedFiles > 0 && impactedRows.projectFiles > 0) warnings.push("Target and source aliases both have indexed files; execution must de-duplicate source_uri/content_hash rows.");
  if (target.memoryItems > 0 && impactedRows.memoryItems > 0) warnings.push("Target and source aliases both have memory items; execution should preserve provenance and avoid duplicate summaries.");
  if (new Set([target.profile, ...sources.map((source) => source.profile)]).size > 1) warnings.push("Project aliases use different profiles; execution must choose a final profile intentionally.");
  if (sources.some((source) => source.rootUri.startsWith("/home/")) && target.rootUri.startsWith("/Users/")) warnings.push("Linux and macOS home aliases are present; keep path mapping documented for shared shared host storage.");
  return warnings;
}

function formatDashboardProjectAliasMergePlan(plan: DashboardProjectAliasMergePlan): string {
  const lines = [
    `Project alias merge plan (${plan.dryRun ? "dry-run" : "execute"})`,
    `Generated: ${plan.generatedAt}`,
    `Identities: ${plan.identityCount}`,
    `Registered projects: ${plan.projectCount}`,
    `Merge candidates: ${plan.candidateCount}`,
    `Source project rows: ${plan.sourceProjectCount}`,
    "",
    ...plan.summary.map((item) => `- ${item}`)
  ];
  for (const group of plan.groups) {
    lines.push(
      "",
      `## ${group.target.name}`,
      `Canonical: ${group.canonicalRootUri}`,
      `Target: ${group.target.id} ${group.target.rootUri}`,
      `Risk: ${group.risk}`,
      `Sources: ${group.sources.length}`,
      `Impact: ${group.impactedRows.workflowRuns} runs, ${group.impactedRows.projectFiles} indexed files, ${group.impactedRows.memoryItems} memory items, ${group.impactedRows.activeRuns} active runs`
    );
    for (const source of group.sources) {
      lines.push(`- ${source.id} ${source.rootUri} (${source.runCount} runs, ${source.indexedFiles} files, ${source.memoryItems} memory)`);
    }
    if (group.conflictWarnings.length) {
      lines.push("Warnings:");
      for (const warning of group.conflictWarnings) lines.push(`- ${warning}`);
    }
  }
  return lines.join("\n");
}

async function loadDashboardProjectContextFiles(projectRootUri: string): Promise<DashboardProjectDetail["contextFiles"]> {
  const files = [
    ["AGENTS.md", "AGENTS.md"],
    ["Project Policy", ".agent-workflow/project.yaml"],
    ["Context", ".agent-workflow/context.md"],
    ["Commands", ".agent-workflow/commands.md"],
    ["Decisions", ".agent-workflow/decisions.md"],
    ["Schedules", ".agent-workflow/schedules.yaml"]
  ] as const;
  return Promise.all(files.map(async ([label, relativePath]) => {
    try {
      const raw = await fs.readFile(path.join(projectRootUri, relativePath), "utf8");
      return {
        label,
        relativePath,
        exists: true,
        preview: previewText(raw)
      };
    } catch {
      return {
        label,
        relativePath,
        exists: false,
        preview: ""
      };
    }
  }));
}

function previewText(value: string): string {
  const trimmed = value.trim();
  if (trimmed.length <= 500) {
    return trimmed;
  }
  return `${trimmed.slice(0, 500)}\n...`;
}

async function buildRunUsageEstimate(input: {
  run: DashboardRunStatus;
  artifacts: Awaited<ReturnType<typeof listArtifacts>>;
  routedStages: number;
  projectTokenTotals?: Map<string, number>;
}): Promise<RunUsageEstimate> {
  const compiledBriefText = compiledBriefTextFromArtifacts(input.artifacts);
  const compiledBriefTokens = estimateDashboardTokens(compiledBriefText);
  const selectedSourceTokens = sumApproxSourceTokens(compiledBriefText);
  const indexedProjectTokens = await loadIndexedProjectTokenTotal(input.run.projectRootUri, input.projectTokenTotals);
  const routedStages = Math.max(1, input.routedStages);
  const estimatedPromptTokens = compiledBriefTokens * routedStages;
  const estimatedBaselineTokens = Math.max(indexedProjectTokens, selectedSourceTokens, compiledBriefTokens) * routedStages;
  const estimatedTokensSaved = Math.max(0, estimatedBaselineTokens - estimatedPromptTokens);

  return {
    runId: input.run.id,
    routedStages,
    indexedProjectTokens,
    compiledBriefTokens,
    selectedSourceTokens,
    estimatedPromptTokens,
    estimatedBaselineTokens,
    estimatedTokensSaved,
    tokenReductionPercent: estimatedBaselineTokens > 0 ? Math.round((estimatedTokensSaved / estimatedBaselineTokens) * 100) : null,
    runDurationMs: runDurationMs(input.run)
  };
}

async function loadIndexedProjectTokenTotal(projectRootUri: string, cache = new Map<string, number>()): Promise<number> {
  const cached = cache.get(projectRootUri);
  if (cached !== undefined) {
    return cached;
  }
  try {
    const summaries = await listProjectFileSummaries({
      projectRootUri,
      limit: 5000
    });
    const total = summaries.reduce((sum, summary) => sum + summary.tokenEstimate, 0);
    cache.set(projectRootUri, total);
    return total;
  } catch {
    cache.set(projectRootUri, 0);
    return 0;
  }
}

function compiledBriefTextFromArtifacts(artifacts: Awaited<ReturnType<typeof listArtifacts>>): string {
  const artifact = artifacts.find((item) => item.kind === "compiled_brief");
  if (!artifact) {
    return "";
  }
  const text = artifact.content.text;
  if (typeof text === "string") {
    return text;
  }
  return JSON.stringify(artifact.content);
}

function sumApproxSourceTokens(text: string): number {
  return [...text.matchAll(/Approx tokens:\s*(\d+)/gu)]
    .reduce((sum, match) => sum + Number(match[1]), 0);
}

function estimateDashboardTokens(text: string): number {
  if (!text.trim()) {
    return 0;
  }
  return Math.ceil(text.length / 4);
}

function runDurationMs(run: DashboardRunStatus): number | null {
  if (!run.finishedAt) {
    return null;
  }
  const started = Date.parse(run.startedAt);
  const finished = Date.parse(run.finishedAt);
  if (!Number.isFinite(started) || !Number.isFinite(finished) || finished < started) {
    return null;
  }
  return finished - started;
}

function countDashboardStages(stages: CostQualityReport["stages"], keyFor: (stage: CostQualityReport["stages"][number]) => string): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const stage of stages) {
    const key = keyFor(stage);
    counts[key] = (counts[key] ?? 0) + 1;
  }
  return counts;
}

async function loadPreferenceScorecard(input: {
  projectDir: string;
  limit: number;
}): Promise<PreferenceScorecard> {
  const runs = await listWorkflowRunsForProject({
    projectRootUri: input.projectDir,
    limit: input.limit
  });
  const reports: CostQualityReport[] = [];
  for (const run of runs) {
    const details = await getWorkflowRunDetails(run.id);
    if (!details.run) {
      continue;
    }
    const artifacts = await listArtifacts({ runId: run.id });
    reports.push(buildCostQualityReport({
      run: details.run,
      tasks: details.tasks,
      receipts: details.receipts,
      artifacts
    }));
  }
  return buildPreferenceScorecard({
    projectRootUri: input.projectDir,
    reports
  });
}

async function loadTuningProposals(input: {
  projectDir: string;
  limit: number;
}): Promise<TuningProposalSet> {
  const scorecard = await loadPreferenceScorecard(input);
  return buildTuningProposals(scorecard);
}

async function loadLearningReport(input: {
  projectDir: string;
  limit: number;
}): Promise<LearningReport> {
  const projectDir = path.resolve(process.cwd(), input.projectDir);
  const limit = Math.max(1, input.limit);
  const runs = await listWorkflowRunsForProject({ projectRootUri: projectDir, limit });
  const scorecard = await loadPreferenceScorecard({ projectDir, limit });
  const proposals = buildTuningProposals(scorecard);
  const routeFeedback = summarizeLearningRouteFeedback(await readRouteDecisionFeedbackLog(projectDir));
  const stageHealth = runs.length ? await listWorkflowStageHealthForRuns({ runIds: runs.map((run) => run.id) }) : [];
  const evaluationRuns = runs.filter((run) => typeof run.evaluationMetadata?.suiteId === "string");
  const reports = (await Promise.all(runs.slice(0, Math.min(runs.length, 20)).map((run) => loadCostQualityReport(run.id)))).filter((report): report is CostQualityReport => report !== null);
  const failedRuns = runs
    .filter((run) => run.status === "failed")
    .slice(0, 10)
    .map((run) => ({
      runId: run.id,
      workflowId: run.workflowId,
      task: run.task,
      startedAt: run.startedAt
    }));
  const repeatedFailurePatterns = stageHealth
    .filter((stage) => stage.failedTasks > 0)
    .map((stage) => ({
      workflowId: inferStageWorkflowId(runs, reports, stage.stageId),
      stageId: stage.stageId,
      agentId: inferStageAgentId(reports, stage.stageId),
      failedTasks: stage.failedTasks,
      totalTasks: stage.totalTasks,
      failureRate: stage.totalTasks > 0 ? Number((stage.failedTasks / stage.totalTasks).toFixed(3)) : 0
    }))
    .sort((left, right) => right.failedTasks - left.failedTasks || right.failureRate - left.failureRate)
    .slice(0, 10);
  const costOpportunities = scorecard.groups
    .filter((group) => group.recommendation !== "Keep current routing." || group.fallbackRate > 0 || (group.averageLatencyMs ?? 0) > 30_000)
    .sort((left, right) => right.feedbackScore - left.feedbackScore || right.fallbackRate - left.fallbackRate)
    .slice(0, 10)
    .map((group) => ({
      workflowId: group.workflowId,
      stageId: group.stageId,
      agentId: group.agentId,
      providerId: group.providerId,
      modelTier: group.modelTier,
      runs: group.runs,
      fallbackRate: group.fallbackRate,
      averageLatencyMs: group.averageLatencyMs,
      recommendation: group.recommendation
    }));
  const proposalKinds = countStrings(proposals.proposals.map((proposal) => proposal.kind));
  const evalGaps: string[] = [];
  if (runs.length === 0) evalGaps.push("Run at least one workflow before learning can identify patterns.");
  if (Object.values(scorecard.feedbackCounts).reduce((sum, value) => sum + value, 0) === 0) evalGaps.push("Record accepted, revised, or rejected feedback so learning can personalize recommendations.");
  if (evaluationRuns.length === 0) evalGaps.push("Run or create an evaluation suite before promoting routing, prompt, or context-budget changes.");
  if (failedRuns.length > 0 && repeatedFailurePatterns.length === 0) evalGaps.push("Failed runs exist, but stage-level health did not isolate a repeated failing stage yet.");
  if (proposals.proposals.some((proposal) => proposal.kind === "feedback_needed")) evalGaps.push("Some routes need human feedback before the daemon can rank them confidently.");
  if (!evalGaps.length) evalGaps.push("Learning evidence is ready for autonomous low/medium local optimization and high-risk approval review.");
  return {
    kind: "agentflow_learning_report",
    generatedAt: new Date().toISOString(),
    projectDir,
    limit,
    autonomyMode: "autonomous-local",
    runsAnalyzed: runs.length,
    runStatusCounts: countStrings(runs.map((run) => run.status)),
    feedbackCounts: scorecard.feedbackCounts,
    routeFeedback,
    evaluationRuns: evaluationRuns.length,
    latestEvaluationAt: evaluationRuns.map((run) => run.startedAt).sort().at(-1) ?? null,
    failedRuns,
    repeatedFailurePatterns,
    costOpportunities,
    proposalPreview: {
      total: proposals.proposals.length,
      highPriority: proposals.proposals.filter((proposal) => proposal.priority === "high").length,
      byKind: proposalKinds
    },
    evalGaps,
    safeAutomaticActions: [
      "Read local run history, receipts, feedback, eval summaries, and queue status.",
      "Detect repeated failures, high-cost routes, stale context, and eval gaps.",
      "Use route-decision helpful/costly feedback to prioritize local routing improvements.",
      "Generate compact local learning reports and proposal previews.",
      "Update learning files and future learning database rows that Agent Workflow created and owns by default.",
      "Refresh workflow-shape and agent-type recommendation files automatically when the autonomous optimizer is enabled.",
      "Auto-approve and apply low/medium-risk project-local tuning overlays when autonomous mode is enabled.",
      "Prepare approval queues only for high-risk or outside-boundary changes."
    ],
    approvalRequiredActions: [
      "Apply high-risk project-local changes such as generated eval suites or debug workflow execution.",
      "Promote workflow-shape recommendations into shared workflows or reusable agent cards.",
      "Modify reusable agents, workflows, package code, docs, schemas, provider settings, or project source.",
      "Run commands, tests, web/model research, network calls, or external tools.",
      "Change production policy, deployment, storage lifecycle, server mode, or any private-data export."
    ],
    privacyBoundaries: [
      "Local evidence stays on this machine by default.",
      "Web/model research is opt-in and must not include private source, feedback, logs, prompts, eval cases, or artifacts without explicit approval.",
      "Open-source learning should generalize developer workflow patterns and avoid product-specific behavior."
    ],
    nextCommands: [
      `npm run agentflow -- learning-report --project ${shellQuote(projectDir)} --json`,
      `npm run agentflow -- learning-proposals --project ${shellQuote(projectDir)} --write`,
      `npm run agentflow -- preference-scorecard --project ${shellQuote(projectDir)}`,
      `npm run agentflow -- tuning-proposals --project ${shellQuote(projectDir)}`,
      `npm run agentflow -- run-and-watch model-improvement --project ${shellQuote(projectDir)} --task "Improve local developer workflow quality and cost"`
    ]
  };
}

function summarizeLearningRouteFeedback(log: RouteDecisionFeedbackLog): LearningRouteFeedbackSummary {
  const groups = new Map<string, LearningRouteFeedbackGroup>();
  for (const event of log.events) {
    const target = `${event.workflowId}/${event.stageId}/${event.agentId}`;
    const route = `${event.providerId}/${event.modelTier}`;
    const key = `${target}:${route}:${event.routeClass}`;
    const existing = groups.get(key) ?? {
      target,
      route,
      routeClass: event.routeClass,
      total: 0,
      helpful: 0,
      costly: 0,
      neutral: 0,
      latestAt: null
    };
    existing.total += 1;
    existing[event.rating] += 1;
    existing.latestAt = latestIso(existing.latestAt, event.createdAt);
    groups.set(key, existing);
  }
  const sorted = [...groups.values()].sort((left, right) =>
    right.total - left.total ||
    (right.latestAt ?? "").localeCompare(left.latestAt ?? "") ||
    left.target.localeCompare(right.target)
  );
  const counts = countStrings(log.events.map((event) => event.rating));
  return {
    total: log.events.length,
    counts,
    latestAt: log.events.map((event) => event.createdAt).sort().at(-1) ?? null,
    costlyGroups: sorted.filter((group) => group.costly > 0).sort((left, right) => right.costly - left.costly || right.total - left.total).slice(0, 8),
    helpfulGroups: sorted.filter((group) => group.helpful > 0).sort((left, right) => right.helpful - left.helpful || right.total - left.total).slice(0, 8)
  };
}

function latestIso(left: string | null, right: string): string {
  return !left || right > left ? right : left;
}

function inferStageWorkflowId(runs: DashboardRunStatus[], reports: CostQualityReport[], stageId: string): string {
  const report = reports.find((item) => item.stages.some((stage) => stage.stageId === stageId));
  return report?.workflowId ?? runs[0]?.workflowId ?? "unknown";
}

function inferStageAgentId(reports: CostQualityReport[], stageId: string): string {
  const stage = reports.flatMap((report) => report.stages).find((item) => item.stageId === stageId);
  return stage?.agentId ?? "unknown";
}

async function loadWorkflowShapeOptimization(input: {
  projectDir: string;
  workflowId?: string;
  limit: number;
}): Promise<WorkflowShapeOptimizationReport> {
  const projectDir = path.resolve(process.cwd(), input.projectDir);
  const limit = Math.max(1, input.limit);
  const workflows = await loadWorkflows(rootDir);
  const runs = await listWorkflowRunsForProject({ projectRootUri: projectDir, limit });
  const requestedWorkflow = input.workflowId ? resolveWorkflow(workflows, input.workflowId) : null;
  const workflow = requestedWorkflow
    ?? workflows.find((item) => item.id === runs[0]?.workflowId)
    ?? workflows.find((item) => item.id === "build-feature")
    ?? workflows[0];
  if (!workflow) {
    throw new Error("No reusable workflows are available.");
  }
  if (input.workflowId && !requestedWorkflow) {
    throw new Error(`Unknown workflow: ${input.workflowId}`);
  }
  const workflowRuns = runs.filter((run) => run.workflowId === workflow.id);
  const scorecard = await loadPreferenceScorecard({ projectDir, limit });
  const stageHealth = workflowRuns.length ? await listWorkflowStageHealthForRuns({ runIds: workflowRuns.map((run) => run.id) }) : [];
  const files = await listProjectFileSummaries({ projectRootUri: projectDir, limit: 500 });
  const evaluationRuns = workflowRuns.filter((run) => typeof run.evaluationMetadata?.suiteId === "string");
  return buildWorkflowShapeOptimizationReport({
    projectRootUri: projectDir,
    workflowId: workflow.id,
    workflowName: workflow.name,
    runsAnalyzed: workflowRuns.length,
    evaluationRuns: evaluationRuns.length,
    feedbackCounts: scorecard.feedbackCounts,
    stages: workflow.stages.map((stage, index) => ({
      id: stage.id,
      agentId: stage.agent,
      order: index,
      contextMaxTokens: stage.context.max_tokens,
      contextLoads: stage.context.load,
      approvalRequired: stage.approval_required,
      subagentCount: stage.subagents.length
    })),
    stageHealth,
    scoreGroups: scorecard.groups,
    projectContext: {
      indexedFiles: files.length,
      indexedTokenEstimate: files.reduce((sum, file) => sum + file.tokenEstimate, 0),
      sourceKinds: summarizeProjectSourceKinds(files)
    }
  });
}

function summarizeProjectSourceKinds(files: Awaited<ReturnType<typeof listProjectFileSummaries>>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const file of files) {
    const extension = path.extname(file.sourceUri).replace(/^\./, "") || "none";
    counts[extension] = (counts[extension] ?? 0) + 1;
  }
  return counts;
}

async function writeWorkflowShapeOptimization(projectDir: string, report: WorkflowShapeOptimizationReport): Promise<void> {
  const learningDir = path.join(projectDir, ".agent-workflow", "learning");
  await ensureProjectSubdir(projectDir, learningDir, ".agent-workflow/learning");
  await fs.writeFile(path.join(learningDir, "workflow-shape-proposals.json"), `${JSON.stringify(report, null, 2)}\n`, "utf8");
  await fs.writeFile(path.join(learningDir, "stage-recommendations.md"), formatWorkflowShapeOptimizationMarkdown(report), "utf8");
}

async function loadAgentImprovementReport(input: {
  projectDir: string;
  agentId?: string;
  limit: number;
  mode: AgentImprovementReport["mode"];
}): Promise<AgentImprovementReport> {
  const projectDir = path.resolve(process.cwd(), input.projectDir);
  const limit = Math.max(1, input.limit);
  const agentRecords = await loadAgentImprovementRecords(projectDir);
  const workflows = await loadWorkflows(rootDir);
  const runs = await listWorkflowRunsForProject({ projectRootUri: projectDir, limit });
  const scorecard = await loadPreferenceScorecard({ projectDir, limit });
  const reports = (await Promise.all(runs.slice(0, Math.min(runs.length, 20)).map((run) => loadCostQualityReport(run.id)))).filter((report): report is CostQualityReport => report !== null);
  const stageHealth = runs.length ? await listWorkflowStageHealthForRuns({ runIds: runs.map((run) => run.id) }) : [];
  const workflowStageRefs = new Map<string, Array<{ workflowId: string; stageId: string; subagent: boolean }>>();
  for (const workflow of workflows) {
    for (const stage of workflow.stages) {
      const refs = workflowStageRefs.get(stage.agent) ?? [];
      refs.push({ workflowId: workflow.id, stageId: stage.id, subagent: false });
      workflowStageRefs.set(stage.agent, refs);
      for (const subagent of stage.subagents) {
        const subrefs = workflowStageRefs.get(subagent) ?? [];
        subrefs.push({ workflowId: workflow.id, stageId: stage.id, subagent: true });
        workflowStageRefs.set(subagent, subrefs);
      }
    }
  }

  const focusedRecords = input.agentId
    ? agentRecords.filter((record) => record.agent.id === input.agentId)
    : agentRecords;
  const candidates = focusedRecords
    .map((record) => buildAgentImprovementCandidate({
      record,
      workflowRefs: workflowStageRefs.get(record.agent.id) ?? [],
      runs,
      scorecard,
      reports,
      stageHealth
    }))
    .filter((candidate): candidate is AgentImprovementCandidate => candidate !== null)
    .sort((left, right) => priorityRank(right.priority) - priorityRank(left.priority) || agentImprovementRiskRank(left.riskLevel) - agentImprovementRiskRank(right.riskLevel) || left.agentId.localeCompare(right.agentId));

  const sharedAgents = agentRecords.filter((record) => record.scope === "shared").length;
  const projectLocalAgents = agentRecords.filter((record) => record.scope === "project-local").length;
  const workflowReferences = [...workflowStageRefs.values()].reduce((sum, refs) => sum + refs.length, 0);
  return {
    kind: "agentflow_agent_improvement_report",
    generatedAt: new Date().toISOString(),
    projectRootUri: projectDir,
    limit,
    mode: input.mode,
    agentsAnalyzed: focusedRecords.length,
    candidates,
    evidenceSummary: {
      runsAnalyzed: runs.length,
      workflowReferences,
      projectLocalAgents,
      sharedAgents,
      feedbackCounts: scorecard.feedbackCounts,
      failedRuns: runs.filter((run) => run.status === "failed").length
    },
    ownedLearningFiles: [
      ".agent-workflow/learning/agent-improvement-report.json",
      ".agent-workflow/learning/agent-improvement-recommendations.md"
    ],
    autonomyBoundary: {
      automatic: [
        "Generate role-specific agent improvement candidates from local run evidence and static agent-card quality checks.",
        "Write Agent Workflow-owned learning reports under .agent-workflow/learning when --write or daemon-owned writes are enabled.",
        "Draft safe research queries from generic agent role names and abstract evidence labels without exporting private source or logs."
      ],
      approvalRequired: [
        "Edit shared agents/**/*.yaml or project-local .agent-workflow/agents/*.yaml.",
        "Add new reusable agent types, new tool privileges, broader autonomy, or weaker safety boundaries.",
        "Run network/model research with private project details, prompts, logs, eval cases, or source snippets.",
        "Promote an agent-card improvement into a release bundle."
      ]
    },
    privacyBoundaries: [
      "The report uses local metadata, run status, stage health, feedback counts, and compact report summaries.",
      "Generated research queries are intentionally abstract: job title, public practice area, and generic quality goal only.",
      "No private source, prompts, secrets, logs, or customer/project-specific data should be sent to web/model research without explicit approval."
    ],
    nextCommands: [
      `npm run agentflow -- agent-improvement-report --project ${shellQuote(projectDir)} --write`,
      `npm run agentflow -- agent-task technical-architect --project ${shellQuote(projectDir)} --task "Review agent improvement candidates and identify safe low-risk agent-card patches"`,
      `npm run agentflow -- learning-report --project ${shellQuote(projectDir)} --json`,
      `npm run agentflow -- learning-workflow-shape --project ${shellQuote(projectDir)} --write`
    ]
  };
}

async function loadAgentImprovementRecords(projectDir: string): Promise<Array<{
  agent: AgentCard;
  sourcePath: string;
  scope: "shared" | "project-local";
}>> {
  const sharedRecords = await loadAgentRecords(rootDir);
  const records: Array<{
    agent: AgentCard;
    sourcePath: string;
    scope: "shared" | "project-local";
  }> = sharedRecords.map((record) => ({
    agent: record.value,
    sourcePath: record.path,
    scope: "shared" as const
  }));
  const projectAgentsDir = path.join(projectDir, ".agent-workflow", "agents");
  const entries = await fs.readdir(projectAgentsDir, { withFileTypes: true }).catch(() => [] as Dirent[]);
  for (const entry of entries) {
    if (!entry.isFile() || !entry.name.endsWith(".yaml")) {
      continue;
    }
    const filePath = path.join(projectAgentsDir, entry.name);
    records.push({
      agent: await loadYamlFile(filePath, agentCardSchema),
      sourcePath: path.relative(projectDir, filePath),
      scope: "project-local"
    });
  }
  const merged = new Map<string, typeof records[number]>();
  for (const record of records) {
    merged.set(record.agent.id, record);
  }
  return [...merged.values()];
}

function buildAgentImprovementCandidate(input: {
  record: { agent: AgentCard; sourcePath: string; scope: "shared" | "project-local" };
  workflowRefs: Array<{ workflowId: string; stageId: string; subagent: boolean }>;
  runs: Awaited<ReturnType<typeof listWorkflowRunsForProject>>;
  scorecard: PreferenceScorecard;
  reports: CostQualityReport[];
  stageHealth: Awaited<ReturnType<typeof listWorkflowStageHealthForRuns>>;
}): AgentImprovementCandidate | null {
  const { agent } = input.record;
  const joined = [
    agent.purpose,
    ...agent.use_when,
    ...agent.avoid_when,
    ...agent.can,
    ...agent.cannot,
    ...agent.requires_approval,
    agent.prompt
  ].join("\n").toLowerCase();
  const workflowRefs = input.workflowRefs;
  const usedStageIds = new Set(workflowRefs.map((ref) => ref.stageId));
  const failingStages = input.stageHealth.filter((stage) => usedStageIds.has(stage.stageId) && stage.failedTasks > 0);
  const costGroups = input.scorecard.groups.filter((group) => group.agentId === agent.id || usedStageIds.has(group.stageId));
  const fallbackGroups = costGroups.filter((group) => group.fallbackRate > 0 || (group.averageLatencyMs ?? 0) > 30_000);
  const evidence: string[] = [];
  const mutableFields = new Set<AgentImprovementCandidate["suggestedMutableFields"][number]>();
  const recommendations: string[] = [];
  let priority: LearningProposalPriority = "low";
  let riskLevel: LearningRiskLevel = "low";

  if (workflowRefs.length) {
    evidence.push(`Referenced by ${workflowRefs.length} workflow stage/subagent slot(s).`);
  } else {
    evidence.push("No reusable workflow references this agent yet.");
    recommendations.push("Clarify when this agent should be selected, or keep it out of default workflows until evidence supports it.");
    mutableFields.add("use_when");
    priority = "medium";
  }
  if (failingStages.length) {
    const failed = failingStages.reduce((sum, stage) => sum + stage.failedTasks, 0);
    const total = failingStages.reduce((sum, stage) => sum + stage.totalTasks, 0);
    evidence.push(`${failed}/${total} recent task(s) failed in stages connected to this agent.`);
    recommendations.push("Add stronger failure-mode handling, handoff expectations, and verification receipts for stages this agent touches.");
    mutableFields.add("prompt");
    mutableFields.add("outputs");
    priority = "high";
    riskLevel = "medium";
  }
  if (fallbackGroups.length) {
    evidence.push(`${fallbackGroups.length} routing/cost group(s) show fallback or high latency pressure.`);
    recommendations.push("Tune model-tier guidance and context budget so the router can choose cheaper fast models for routine work and reasoning models for risky work.");
    mutableFields.add("context_budget");
    mutableFields.add("prompt");
    priority = priority === "high" ? priority : "medium";
  }
  if (!joined.includes("receipt")) {
    evidence.push("Agent card does not explicitly require receipts or auditable evidence.");
    recommendations.push("Add receipt language so autonomous actions leave compact proof of what changed, why, and how it was verified.");
    mutableFields.add("prompt");
  }
  if (!joined.includes("validat") && !joined.includes("test")) {
    evidence.push("Agent card does not strongly name validation or test expectations.");
    recommendations.push("Add role-specific validation expectations before the agent marks work complete.");
    mutableFields.add("prompt");
    mutableFields.add("can");
  }
  if ((agent.category === "automatic" || String(agent.autonomy) === "wide-open") && !agent.requires_approval.length) {
    evidence.push("Automatic/high-autonomy agent has no explicit approval boundary entries.");
    recommendations.push("Add explicit danger gates for destructive commands, network/export behavior, privilege expansion, and shared-definition edits.");
    mutableFields.add("requires_approval");
    priority = "high";
    riskLevel = "medium";
  }
  if ((agent.category === "product" || agent.id.includes("ux")) && !joined.includes("accessib")) {
    evidence.push("Product/UX agent does not explicitly mention accessibility.");
    recommendations.push("Add accessibility, responsive layout, and trust/polish review criteria to the role prompt.");
    mutableFields.add("prompt");
  }
  if ((agent.category === "development" || agent.id.includes("security")) && !joined.includes("secret") && !joined.includes("auth")) {
    evidence.push("Development/security-adjacent agent card does not explicitly mention auth or secret handling.");
    recommendations.push("Add scoped checks for auth boundaries, secrets, permissions, and blast radius when relevant to the role.");
    mutableFields.add("prompt");
  }
  if (!recommendations.length) {
    return null;
  }

  const autoApplyEligible = input.record.scope === "project-local" && agentImprovementRiskRank(riskLevel) <= agentImprovementRiskRank("medium") && !recommendations.some((item) => /autonomy|approval|permission|privilege|network|export/i.test(item));
  return {
    id: `agent-${agent.id.replace(/[^a-z0-9_-]/gi, "-")}-improvement`,
    agentId: agent.id,
    displayName: agent.display_name,
    scope: input.record.scope,
    category: agent.category,
    priority,
    riskLevel,
    sourcePath: input.record.sourcePath,
    currentRoleSummary: agent.purpose,
    evidence: evidence.slice(0, 6),
    recommendation: dedupeStrings(recommendations).join(" "),
    suggestedMutableFields: [...mutableFields],
    safeResearchQueries: buildSafeAgentImprovementResearchQueries(agent),
    validationPlan: [
      "Validate updated agent YAML against the registry schema.",
      "Run npm run validate and npm run contract-test.",
      "Compare a small holdout set of recent tasks before/after the candidate prompt change.",
      "Check cost, fallback, failure, and user-feedback deltas before promotion."
    ],
    autoApplyEligible,
    approvalRequired: !autoApplyEligible
  };
}

function buildSafeAgentImprovementResearchQueries(agent: AgentCard): string[] {
  const role = agent.display_name || agent.id;
  const category = agent.category;
  return [
    `best practices for ${role} AI agent role in software development workflows`,
    `evaluation checklist for ${category} AI coding agent quality and reliability`,
    `prompt design patterns for ${role} agent receipts validation and handoffs`
  ];
}

function priorityRank(priority: LearningProposalPriority): number {
  return priority === "high" ? 3 : priority === "medium" ? 2 : 1;
}

function agentImprovementRiskRank(risk: LearningRiskLevel): number {
  return risk === "high" ? 3 : risk === "medium" ? 2 : 1;
}

function dedupeStrings(items: string[]): string[] {
  return [...new Set(items)];
}

async function writeAgentImprovementReport(projectDir: string, report: AgentImprovementReport): Promise<void> {
  const learningDir = path.join(projectDir, ".agent-workflow", "learning");
  await ensureProjectSubdir(projectDir, learningDir, ".agent-workflow/learning");
  await fs.writeFile(path.join(learningDir, "agent-improvement-report.json"), `${JSON.stringify(report, null, 2)}\n`, "utf8");
  await fs.writeFile(path.join(learningDir, "agent-improvement-recommendations.md"), formatAgentImprovementMarkdown(report), "utf8");
}

async function buildAgentImprovementPatchPlan(projectDir: string, report: AgentImprovementReport, ids: string[] | "all"): Promise<AgentImprovementPatchPlan> {
  const candidates = report.candidates.filter((candidate) => ids === "all" || ids.includes(candidate.id) || ids.includes(candidate.agentId));
  const selectedIds = candidates.map((candidate) => candidate.id);
  const skippedIds = ids === "all" ? [] : ids.filter((id) => !selectedIds.includes(id) && !candidates.some((candidate) => candidate.agentId === id));
  const records = await loadAgentImprovementRecords(projectDir);
  const recordById = new Map(records.map((record) => [record.agent.id, record]));
  const patches: AgentImprovementPatch[] = [];
  for (const candidate of candidates) {
    const record = recordById.get(candidate.agentId);
    if (!record) {
      continue;
    }
    const absoluteSourcePath = resolveAgentImprovementSourcePath(projectDir, record);
    const sourceYaml = await fs.readFile(absoluteSourcePath, "utf8");
    const sourceHash = sha256(sourceYaml);
    const proposedAgent = proposeAgentImprovement(record.agent, candidate);
    const validation = agentCardSchema.safeParse(proposedAgent);
    const proposedYaml = YAML.stringify(proposedAgent);
    patches.push({
      id: `patch-${candidate.id}`,
      candidateId: candidate.id,
      agentId: candidate.agentId,
      displayName: candidate.displayName,
      scope: candidate.scope,
      sourcePath: candidate.sourcePath,
      sourceHash,
      priority: candidate.priority,
      riskLevel: candidate.riskLevel,
      approvalRequired: candidate.approvalRequired || candidate.scope === "shared",
      autoApplyEligible: candidate.autoApplyEligible && candidate.scope === "project-local" && validation.success,
      changedFields: candidate.suggestedMutableFields,
      rationale: candidate.recommendation,
      validation: {
        schemaValid: validation.success,
        errors: validation.success ? [] : validation.error.issues.map((issue) => `${issue.path.join(".") || "root"}: ${issue.message}`)
      },
      unifiedDiff: buildUnifiedDiff(candidate.sourcePath, sourceYaml, proposedYaml),
      proposedYaml,
      rollback: {
        restoreSourceHash: sourceHash,
        restorePath: candidate.sourcePath
      }
    });
  }

  return {
    kind: "agentflow_agent_improvement_patch_plan",
    generatedAt: new Date().toISOString(),
    projectRootUri: projectDir,
    sourceReportGeneratedAt: report.generatedAt,
    selectedIds,
    skippedIds,
    patches,
    summary: [
      `${patches.length} agent improvement patch preview(s) generated.`,
      `${patches.filter((patch) => patch.validation.schemaValid).length} schema-valid preview(s).`,
      `${patches.filter((patch) => patch.autoApplyEligible).length} low-risk project-local preview(s) would be eligible for a future explicit auto-apply setting.`,
      `${patches.filter((patch) => patch.approvalRequired).length} preview(s) require approval before touching agent YAML.`
    ],
    ownedLearningFiles: [
      ".agent-workflow/learning/agent-improvement-patches.json",
      ".agent-workflow/learning/agent-improvement-patches.md"
    ]
  };
}

function resolveAgentImprovementSourcePath(projectDir: string, record: { sourcePath: string; scope: "shared" | "project-local" }): string {
  return record.scope === "shared"
    ? path.join(rootDir, record.sourcePath)
    : path.join(projectDir, record.sourcePath);
}

function proposeAgentImprovement(agent: AgentCard, candidate: AgentImprovementCandidate): AgentCard {
  const proposed = structuredClone(agent);
  const notes = buildAgentImprovementPromptNotes(candidate);
  if (candidate.suggestedMutableFields.includes("prompt")) {
    proposed.prompt = appendAgentPromptNotes(proposed.prompt, notes);
  }
  if (candidate.suggestedMutableFields.includes("can")) {
    proposed.can = addUniqueStrings(proposed.can, ["Produce role-specific validation evidence before handoff."]);
  }
  if (candidate.suggestedMutableFields.includes("requires_approval")) {
    proposed.requires_approval = addUniqueStrings(proposed.requires_approval, [
      "Destructive commands, external network or export actions, privilege expansion, provider changes, and edits to shared reusable definitions."
    ]);
  }
  if (candidate.suggestedMutableFields.includes("context_budget")) {
    proposed.context_budget = {
      ...proposed.context_budget,
      preferred_sources: addUniqueStrings(proposed.context_budget.preferred_sources, ["recent relevant receipts", "evaluation evidence", "project-local tuning notes"])
    };
  }
  if (candidate.suggestedMutableFields.includes("outputs")) {
    proposed.outputs = {
      ...proposed.outputs,
      schema: proposed.outputs.schema || "structured_summary"
    };
  }
  return proposed;
}

function buildAgentImprovementPromptNotes(candidate: AgentImprovementCandidate): string {
  const bullets = [
    "Leave compact receipts for autonomous or delegated work, including what changed, why, and how it was checked.",
    "Name the validation evidence needed before handoff, scaled to the risk of the task.",
    candidate.category === "product" ? "Include accessibility, responsive behavior, user trust, and polish in product-surface reviews." : "",
    candidate.category === "development" ? "Check auth, secret handling, permissions, and blast radius when the task touches runtime behavior." : "",
    candidate.category === "automatic" ? "Stop for approval before destructive, external, provider, privilege, or reusable-definition changes." : ""
  ].filter(Boolean);
  return [
    "Local learning improvement notes:",
    ...bullets.map((item) => `- ${item}`)
  ].join("\n");
}

function appendAgentPromptNotes(prompt: string, notes: string): string {
  if (prompt.includes("Local learning improvement notes:")) {
    return prompt;
  }
  return `${prompt.trim()}\n\n${notes}\n`;
}

function addUniqueStrings(values: string[], additions: string[]): string[] {
  const seen = new Set(values);
  const output = [...values];
  for (const addition of additions) {
    if (!seen.has(addition)) {
      output.push(addition);
      seen.add(addition);
    }
  }
  return output;
}

function sha256(value: string): string {
  return createHash("sha256").update(value).digest("hex");
}

function buildUnifiedDiff(filePath: string, before: string, after: string): string {
  if (before === after) {
    return "";
  }
  const beforeLines = before.trimEnd().split("\n");
  const afterLines = after.trimEnd().split("\n");
  return [
    `--- a/${filePath}`,
    `+++ b/${filePath}`,
    "@@ full-file preview @@",
    ...beforeLines.map((line) => `-${line}`),
    ...afterLines.map((line) => `+${line}`)
  ].join("\n");
}

